/// The `genre` of this kit's world file (and the `game.id` default).
pub const GAME_ID: &str = "city_action";

/// True for a world file whose `genre` is this kit's.
pub fn is_city_action_dump(json: &str) -> bool {
    serde_json::from_str::<Value>(json)
        .ok()
        .and_then(|v| {
            v.get("genre")
                .and_then(|g| g.as_str())
                .map(|s| s == GAME_ID)
        })
        .unwrap_or(false)
}

// ---------------------------------------------------------------- spec ----

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct CityActionSpec {
    pub id: String,
    pub title: String,
    /// Run length cap (s). A prototype run is open-ended; this only bounds a session.
    pub secs: f32,
    /// Half size (m) of the square arena.
    pub half: f32,
    /// Hero speed (m/s) and radius (m).
    pub speed: f32,
    pub radius: f32,
    /// Zombie walk speed (m/s) and body radius (m).
    pub zombie_speed: f32,
    pub zombie_radius: f32,
    /// Thumb stick radius in pixels at 400 px of short side, and its dead zone (0..1).
    pub stick_px: f32,
    pub stick_dead: f32,
    pub seed: u32,
    /// Music and sound cues for the page (file names under the bundle). Passed through.
    pub audio: Option<Value>,
    /// The meta round's economy (META-DESIGN §1.3): currency, the earn
    /// formula, the unlock catalog, the permanent-upgrade table and the
    /// loop knobs (loops land in M3; the data rides from M1 so the save
    /// and the fixture never change shape again).
    pub meta: MetaSpec,
}

impl Default for CityActionSpec {
    fn default() -> Self {
        Self {
            id: GAME_ID.into(),
            title: "City Action".into(),
            secs: 600.0,
            half: 30.0,
            speed: 5.4,
            radius: 0.38,
            zombie_speed: 1.9,
            zombie_radius: 0.42,
            stick_px: 70.0,
            stick_dead: 0.12,
            seed: 11,
            audio: Some(default_audio()),
            meta: MetaSpec::default(),
        }
    }
}

impl CityActionSpec {
    pub fn from_value(v: &Value) -> Result<Self, String> {
        let spec: Self =
            serde_json::from_value(v.clone()).map_err(|e| format!("city_action spec: {e}"))?;
        spec.validate()?;
        Ok(spec)
    }

    pub fn validate(&self) -> Result<(), String> {
        let range = |name: &str, v: f32, lo: f32, hi: f32| {
            if v.is_finite() && (lo..=hi).contains(&v) {
                Ok(())
            } else {
                Err(format!("city_action: {name} must be {lo}..={hi}, got {v}"))
            }
        };
        range("secs", self.secs, 5.0, 600.0)?;
        range("half", self.half, 10.0, 40.0)?;
        range("speed", self.speed, 0.5, 20.0)?;
        range("radius", self.radius, 0.1, 2.0)?;
        range("zombie_speed", self.zombie_speed, 0.0, 10.0)?;
        range("zombie_radius", self.zombie_radius, 0.1, 2.0)?;
        range("stick_px", self.stick_px, 20.0, 200.0)?;
        range("stick_dead", self.stick_dead, 0.0, 0.6)?;
        self.meta.validate()
    }
}

// ------------------------------------------------------------- meta ----
// The pre-publish meta round (META-DESIGN, 2026-11-18): a coin economy
// over the campaign save. The catalog is data in this spec — prices,
// costs and scaling tables are JSON-declared and re-tunable without
// code, like every other tuning table in the kit. M1 ships the wallet,
// the arsenal + ★ corners and the permanent upgrades; the companion
// entries ride as data (M2 reads them) and the loop knobs as data
// (M3 reads them), so neither the schema nor the save changes again.

/// The wallet's currency (META-DESIGN §1.3): the engine meta family's
/// coin, named in the kit's own words.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct MetaCurrency {
    pub id: String,
    pub name: String,
}

impl Default for MetaCurrency {
    fn default() -> Self {
        Self {
            id: "coins".into(),
            name: "COINS".into(),
        }
    }
}

/// What a finished run pays (META-DESIGN §1.2):
/// `min(cap, floor(kills × per_kill + score × per_score) + per_boss
/// × bosses + clear)`, credited once in `record_run`.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct MetaEarn {
    pub per_kill: f32,
    pub per_score: f32,
    pub per_boss: u32,
    pub clear: u32,
    pub cap: u32,
}

impl Default for MetaEarn {
    fn default() -> Self {
        Self {
            per_kill: 0.35,
            per_score: 0.05,
            per_boss: 12,
            clear: 40,
            cap: 300,
        }
    }
}

/// One ★ tier of a weapon (META-DESIGN §4): a small damage step plus
/// the presentation set — tint, sword scale and added glow together,
/// because tint alone reads cheap. Tier 1 is ownership itself: price
/// 0 and the shipped look (scale 2.0, silver, no added glow).
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct StarTier {
    pub tier: u32,
    pub price: u32,
    pub dmg: f32,
    pub sword_scale: f32,
    pub tint: [u8; 3],
    pub emissive: f32,
}

impl Default for StarTier {
    fn default() -> Self {
        Self {
            tier: 1,
            price: 0,
            dmg: 0.0,
            sword_scale: 2.0,
            tint: [255, 255, 255],
            emissive: 0.0,
        }
    }
}

/// The ★ ladder every arsenal weapon carries (META-DESIGN §3.3).
fn star_ladder() -> Vec<StarTier> {
    vec![
        StarTier::default(),
        StarTier {
            tier: 2,
            price: 600,
            dmg: 0.04,
            sword_scale: 2.2,
            tint: [255, 214, 130],
            emissive: 0.35,
        },
        StarTier {
            tier: 3,
            price: 1200,
            dmg: 0.08,
            sword_scale: 2.45,
            tint: [255, 170, 90],
            emissive: 0.6,
        },
    ]
}

/// One catalog row (META-DESIGN §1.3/§2.5/§3.3), discriminated by
/// `kind`: a `companion` (M2's feature; the data rides now) or a
/// `weapon` (an arsenal unlock: owning it buys a run *start* with it).
/// A weapon's `model` names the Synty GLB the ult's giant-sword
/// prop wears for that weapon (weapons round, 2026-11-19, §3.4's
/// schema decision landing): equip stays an index swap into the
/// pre-declared prop set — no hero model and no in-hand visual
/// changes (the no-rebake rule, §3.2).
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct CatalogEntry {
    pub id: String,
    pub kind: String,
    pub name: String,
    /// Companions: HEALER / CASTER / BUFFER. Weapons: empty.
    pub role: String,
    pub desc: String,
    pub price: u32,
    /// Weapons: the index into the kit's weapon table.
    pub weapon: Option<usize>,
    /// Companions: the GLB the walker declares at boot (M2). Weapons:
    /// the Synty GLB the ult-sword prop wears (weapons round, §3.4).
    pub model: Option<String>,
    /// Companions: the cast clip the role plays (M2).
    pub clip_cast: Option<String>,
    /// Weapons: the ★ ladder. Companions carry none this round.
    pub stars: Vec<StarTier>,
}

