impl MetaSpec {
    /// The catalog row with this id, if declared.
    pub fn entry(&self, id: &str) -> Option<&CatalogEntry> {
        self.catalog.iter().find(|e| e.id == id)
    }

    /// The catalog row for weapon-table index `idx`, if declared.
    pub fn weapon_entry(&self, idx: usize) -> Option<&CatalogEntry> {
        self.catalog
            .iter()
            .find(|e| e.kind == "weapon" && e.weapon == Some(idx))
    }

    /// The parsed upgrade table (the spec was validated, so this is
    /// the table the kit plays with).
    pub fn upgrade_table(&self) -> UpgradeTable {
        UpgradeTable::from_rows(self.upgrades.clone())
            .unwrap_or_else(|_| UpgradeTable::from_rows(Vec::new()).expect("empty table"))
    }

    fn validate(&self) -> Result<(), String> {
        let bad = |what: &str| format!("city_action meta: {what}");
        if self.currency.id.is_empty() || self.currency.name.is_empty() {
            return Err(bad("the currency must be named"));
        }
        let e = &self.earn;
        if !e.per_kill.is_finite()
            || !e.per_score.is_finite()
            || e.per_kill < 0.0
            || e.per_score < 0.0
            || e.cap == 0
        {
            return Err(bad("the earn rates must be finite, >= 0, with a cap"));
        }
        UpgradeTable::from_rows(self.upgrades.clone()).map_err(|e| bad(&e))?;
        for (i, entry) in self.catalog.iter().enumerate() {
            if entry.id.is_empty() || entry.name.is_empty() {
                return Err(bad(&format!("catalog row {i} must be named")));
            }
            if self.catalog[..i].iter().any(|o| o.id == entry.id) {
                return Err(bad(&format!("duplicate catalog id {}", entry.id)));
            }
            match entry.kind.as_str() {
                "weapon" => {
                    let idx = entry
                        .weapon
                        .ok_or_else(|| bad(&format!("{} names no weapon", entry.id)))?;
                    if idx >= 6 {
                        return Err(bad(&format!(
                            "{}: weapon index {idx} out of range",
                            entry.id
                        )));
                    }
                    for (j, star) in entry.stars.iter().enumerate() {
                        if star.tier != j as u32 + 1 {
                            return Err(bad(&format!(
                                "{}: star tiers must climb 1, 2, 3",
                                entry.id
                            )));
                        }
                        if !star.dmg.is_finite()
                            || !star.sword_scale.is_finite()
                            || !star.emissive.is_finite()
                        {
                            return Err(bad(&format!("{}: star values must be finite", entry.id)));
                        }
                    }
                }
                "companion" => {
                    if entry.role.is_empty() {
                        return Err(bad(&format!("{} must name its role", entry.id)));
                    }
                }
                other => return Err(bad(&format!("unknown catalog kind {other}"))),
            }
        }
        Ok(())
    }
}

/// The player's meta wallet and unlocks (META-DESIGN §1.4): one
/// object inside the campaign save, beside `Progress`'s own keys —
/// `Progress::load` ignores it, and this load ignores `Progress`'s
/// keys, so the two halves cannot corrupt each other. Loading
/// sanitizes the way the house does (clamp, drop, never error): a
/// save written before the meta round loads as a fresh wallet with
/// the campaign intact, and a corrupt `meta` blob does the same.
#[derive(Clone, Debug, PartialEq)]
struct MetaState {
    coins: u32,
    lifetime: u32,
    /// Owned catalog ids, plus `"<weapon id>.<tier>"` for ★ tiers
    /// above 1 (tier 1 is ownership itself).
    owned: Vec<String>,
    equipped_companion: Option<String>,
    equipped_weapon: String,
    upgrades: UpgradeState,
    /// The highest loop unlocked and the loop selected for the
    /// next run (M3 reads them: the beat's dial and the run's
    /// captured difficulty).
    loop_level: u32,
    loop_sel: u32,
}

impl MetaState {
    /// A fresh wallet for a spec: the price-0 rows are owned (the
    /// standard sword, and Megan — the headline is playable in the
    /// very first run), the defaults equipped, every upgrade at 0.
    fn fresh(spec: &MetaSpec, table: &UpgradeTable) -> Self {
        let mut owned: Vec<String> = spec
            .catalog
            .iter()
            .filter(|e| e.price == 0)
            .map(|e| e.id.clone())
            .collect();
        owned.sort();
        let equipped_weapon = spec
            .catalog
            .iter()
            .find(|e| e.kind == "weapon" && e.price == 0)
            .map(|e| e.id.clone())
            .unwrap_or_else(|| "wep.standard".into());
        let equipped_companion = spec
            .catalog
            .iter()
            .find(|e| e.kind == "companion" && e.price == 0)
            .map(|e| e.id.clone());
        let mut upgrades = UpgradeState::new();
        upgrades.load(&json!({}), table);
        Self {
            coins: 0,
            lifetime: 0,
            owned,
            equipped_companion,
            equipped_weapon,
            upgrades,
            loop_level: 1,
            loop_sel: 1,
        }
    }

    /// Read the save's `meta` object over the fresh defaults.
    /// `all_clear` is the campaign's state: a loop above 1 is only
    /// meaningful once every stage is cleared, so without it the
    /// loop fields sanitize back to 1 (META-DESIGN §1.4).
    fn load(&mut self, save: &Value, spec: &MetaSpec, table: &UpgradeTable, all_clear: bool) {
        *self = Self::fresh(spec, table);
        let Some(meta) = save.get("meta").filter(|m| m.is_object()) else {
            return;
        };
        let clamp_coins = |v: Option<&Value>| {
            v.and_then(|c| c.as_u64())
                .map_or(0, |c| c.min(1_000_000_000) as u32)
        };
        self.coins = clamp_coins(meta.get("coins"));
        self.lifetime = clamp_coins(meta.get("lifetime"));
        if let Some(list) = meta.get("owned").and_then(|o| o.as_array()) {
            for raw in list.iter().filter_map(|o| o.as_str()) {
                if spec.entry(raw).is_some() {
                    self.own(raw);
                } else if let Some((base, tier)) = raw.rsplit_once('.') {
                    // A ★ ownership id: valid only over an owned
                    // weapon whose ladder carries the tier.
                    if let (Some(entry), Ok(tier)) = (spec.entry(base), tier.parse::<u32>()) {
                        if entry.kind == "weapon"
                            && tier >= 2
                            && entry.stars.iter().any(|s| s.tier == tier)
                        {
                            self.own(raw);
                        }
                    }
                }
            }
            // A ★ without its weapon is not ownership.
            let bases: Vec<String> = self
                .owned
                .iter()
                .filter(|id| spec.entry(id).is_some())
                .cloned()
                .collect();
            self.owned.retain(|id| {
                spec.entry(id).is_some() || {
                    id.rsplit_once('.')
                        .is_some_and(|(base, _)| bases.iter().any(|b| b == base))
                }
            });
        }
        if let Some(eq) = meta.get("equipped") {
            if let Some(w) = eq.get("weapon").and_then(|w| w.as_str()) {
                if self.owns(w) && spec.entry(w).is_some_and(|e| e.kind == "weapon") {
                    self.equipped_weapon = w.to_string();
                }
            }
            if let Some(c) = eq.get("companion").and_then(|c| c.as_str()) {
                if self.owns(c) && spec.entry(c).is_some_and(|e| e.kind == "companion") {
                    self.equipped_companion = Some(c.to_string());
                }
            }
        }
        if let Some(u) = meta.get("upgrades") {
            self.upgrades.load(u, table);
        }
        if all_clear {
            let clamp_loop = |v: Option<&Value>| {
                v.and_then(|l| l.as_u64())
                    .map_or(1, |l| (l as u32).clamp(1, 99))
            };
            self.loop_level = clamp_loop(meta.get("loop"));
            self.loop_sel = clamp_loop(meta.get("loop_sel")).min(self.loop_level);
        }
    }

    /// The save's `meta` object (META-DESIGN §1.4's shape).
    fn to_value(&self) -> Value {
        json!({
            "v": 1,
            "coins": self.coins,
            "lifetime": self.lifetime,
            "owned": self.owned,
            "equipped": {
                "companion": self.equipped_companion,
                "weapon": self.equipped_weapon,
            },
            "upgrades": self.upgrades.to_value(),
            "loop": self.loop_level,
            "loop_sel": self.loop_sel,
        })
    }

    fn own(&mut self, id: &str) {
        if !self.owned.iter().any(|o| o == id) {
            self.owned.push(id.to_string());
            self.owned.sort();
        }
    }

    fn owns(&self, id: &str) -> bool {
        self.owned.iter().any(|o| o == id)
    }

    /// The ★ tier owned of a weapon entry: 1 for ownership itself,
    /// plus the highest bought tier; 0 when the weapon is unowned.
    fn star_tier(&self, entry: &CatalogEntry) -> u32 {
        if entry.kind != "weapon" || !self.owns(&entry.id) {
            return 0;
        }
        let mut tier = 1;
        for star in &entry.stars {
            if star.tier >= 2 && self.owns(&format!("{}.{}", entry.id, star.tier)) {
                tier = tier.max(star.tier);
            }
        }
        tier
    }
}

