/// Drop rolls use their own stream (design §3.5): the spawn `rng`
/// sequence — and every test pinned to it — must not shift when a kill
/// rolls for loot.
const DROP_SEED_XOR: u32 = 0xD20F_0001;
/// A mob's chance to leave a snack behind (design §3.5).
const MOB_HEAL_CHANCE: f32 = 0.03;
/// At or below this HP the pity counter runs (design §3.5).
const PITY_HP: f32 = 40.0;
/// Kills at low HP, since the last heal drop, that guarantee the next
/// kill drops a snack (design §3.5).
const PITY_KILLS: u32 = 15;
/// A drop's lifetime in seconds (the last 3 blink, design §3.5).
const DROP_TTL: f32 = 18.0;
/// Live drops at once; the oldest is evicted past it (design §3.5).
const DROP_CAP: usize = 8;
/// How close a drop starts sliding to the hero — the survivor kits'
/// shipped magnet radius (design §3.6: their numbers, not the draft's).
const DROP_MAGNET_R: f32 = 3.0;
/// How long a pickup toast stays on screen (design §3.8).
const TOAST_SECS: f32 = 1.2;

// ------------------------------------------------------------- growth ----
//
// XP and level-up choices, ported from the survivor kits (Saka's call,
// 2026-11-15). Dusk Horde (`world_survivor`) is the direct ancestor: a
// gem off every kill, the curve below, a frozen three-card pick whose
// effects accumulate. Moonlit Swarm adds the level-up heal — a share
// of max HP back the moment the level lands. The pool holds only
// picks that move a real stat in this kit: there are no weapon kinds
// to unlock and no fire rate to raise (the sword's tempo is its own),
// so the seven passives lean on damage, body, legs, reach, gauge,
// charge and the dodge.

/// XP needed to leave `level` (Dusk Horde's curve, verbatim): level 1
/// asks five gems, and at one XP off every normal kill the first
/// choice lands inside the first half minute of contact.
pub fn xp_need(level: u32) -> u32 {
    5 + level.saturating_sub(1) * 4
}

/// The hero HP bar's colour for a health fraction: the classic
/// progression Saka asked for — green while healthy, amber when
/// hurt, red in the pity-drop zone. A pure function so the band
/// edges are pinned by a test, not by eyeballing a screenshot.
pub fn hero_hp_color(frac: f32) -> [u8; 4] {
    if frac > 0.5 {
        [110, 220, 130, 235]
    } else if frac > 0.25 {
        [255, 200, 90, 235]
    } else {
        [255, 110, 90, 235]
    }
}

/// The share of max HP a level-up hands back (Moonlit's heal_frac).
const LEVEL_HEAL_FRAC: f32 = 0.3;
/// A gem drop's lifetime in seconds (heals live 18; gems wait longer —
/// they are the run's savings, not its snacks).
const GEM_TTL: f32 = 30.0;
/// Live gems at once; past it the oldest gem is evicted.
const GEM_CAP: usize = 96;
/// Choice rolls draw from their own stream, like drops and kinds: the
/// spawn and loot sequences must not shift when a level is rolled.
const CHOICE_SEED_XOR: u32 = 0xC401_CE04;
/// Mission rolls draw from their own stream too (which mission, which
/// kind it hunts, which weapon cards it offers): a mission firing
/// mid-run must not shift the level-up draws or the drop sequence.
const MISSION_SEED_XOR: u32 = 0x1155_10ED;

/// XP a kill pays, by [`ENEMY_KINDS`] index: normals 1, the heavy 2,
/// the elites pay for their trouble (parasite 5, brute 8).
const KIND_XP: [u32; 10] = [1, 1, 1, 1, 1, 1, 1, 5, 2, 8];
/// XP a boss pays, by its position in the stage's boss order,
/// dealt as a burst of fat gems.
const BOSS_XP: [u32; 3] = [15, 20, 30];
/// The XP value of one boss-burst gem.
const BOSS_GEM_XP: u32 = 5;

/// One growth passive: a stat the level-up cards can raise.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Passive {
    /// Melee and spell damage up.
    Power,
    /// Max HP up (and the growth heals with it).
    Vitality,
    /// Move speed up.
    Speed,
    /// Pickup pull radius up.
    Magnet,
    /// The ult's damage up.
    UltPower,
    /// Magic charge climbs faster.
    Charge,
    /// The dodge rests less between rolls.
    Dodge,
}

/// How many levels one passive holds; a maxed passive leaves the draw.
const PASSIVE_MAX: u32 = 5;
/// Damage multiplier per POWER level (+10%).
const POWER_PER_LV: f32 = 0.10;
/// Max HP (and heal) per VITALITY level.
const VITALITY_PER_LV: f32 = 20.0;
/// Move-speed multiplier per SPEED level (+6%).
const SPEED_PER_LV: f32 = 0.06;
/// Pull radius per MAGNET level (metres).
const MAGNET_PER_LV: f32 = 1.0;
/// Ult-damage multiplier per ULT POWER level (+15%, stacked
/// additively like POWER's own: Lv5 is x1.75, 157.5 over a cast).
const ULT_POWER_PER_LV: f32 = 0.15;
/// Charge-rate multiplier per CHARGE level (+15%).
const CHARGE_PER_LV: f32 = 0.15;
/// Cooldown multiplier per DODGE level (x0.88, so -12%).
const DODGE_PER_LV: f32 = 0.88;
/// The fallback card's heal, as a share of max HP.
const RECOVER_FRAC: f32 = 0.5;

impl Passive {
    const ALL: [Passive; 7] = [
        Passive::Power,
        Passive::Vitality,
        Passive::Speed,
        Passive::Magnet,
        Passive::UltPower,
        Passive::Charge,
        Passive::Dodge,
    ];

    fn index(self) -> usize {
        match self {
            Passive::Power => 0,
            Passive::Vitality => 1,
            Passive::Speed => 2,
            Passive::Magnet => 3,
            Passive::UltPower => 4,
            Passive::Charge => 5,
            Passive::Dodge => 6,
        }
    }

    fn name(self) -> &'static str {
        match self {
            Passive::Power => "POWER",
            Passive::Vitality => "VITALITY",
            Passive::Speed => "SPEED",
            Passive::Magnet => "MAGNET",
            Passive::UltPower => "ULT POWER",
            Passive::Charge => "CHARGE",
            Passive::Dodge => "DODGE",
        }
    }

    /// What one more level buys, in the numbers the player feels.
    fn desc(self) -> &'static str {
        match self {
            Passive::Power => "Damage +10%",
            Passive::Vitality => "Max HP +20, heal 20",
            Passive::Speed => "Move speed +6%",
            Passive::Magnet => "Pickup pull +1.0m",
            Passive::UltPower => "Ult damage +15%",
            Passive::Charge => "Charge speed +15%",
            Passive::Dodge => "Dodge cooldown -12%",
        }
    }
}

/// One card on the level-up screen: a passive that can still grow, or
/// the fallback heal that fills a slot once fewer than three can.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum LevelChoice {
    Passive(Passive),
    Recover,
}

impl LevelChoice {
    fn name(self) -> &'static str {
        match self {
            LevelChoice::Passive(p) => p.name(),
            LevelChoice::Recover => "RECOVER",
        }
    }

    fn desc(self) -> &'static str {
        match self {
            LevelChoice::Passive(p) => p.desc(),
            LevelChoice::Recover => "Heal 50% HP",
        }
    }
}

/// The three level-up card rects (x, y, w, h in HUD pixels), Dusk
/// Horde's layout carried over: one layout shared by the HUD painter
/// and the tap hit-test, so what the player sees is what they tap.
fn level_card_rects(w: f32, h: f32) -> [[f32; 4]; 3] {
    let s = hud_scale(w, h);
    let cw = (w - 36.0 * s).min(340.0 * s);
    let ch = 84.0 * s;
    let gap = 14.0 * s;
    let x = (w - cw) / 2.0;
    let y0 = h * 0.30;
    [
        [x, y0, cw, ch],
        [x, y0 + ch + gap, cw, ch],
        [x, y0 + 2.0 * (ch + gap), cw, ch],
    ]
}

/// Where the stage-select cards sit (v5): the level cards' layout
/// language, one card per stage — stacked rows on a portrait phone,
/// a row of three in landscape. Big targets: a thumb picks the
/// stage, no precision asked. The painter and the hit-test share
/// this, like every button in the kit.
fn stage_card_rects(w: f32, h: f32) -> [[f32; 4]; 3] {
    let s = hud_scale(w, h);
    if h >= w {
        let cw = (w - 36.0 * s).min(360.0 * s);
        let ch = 92.0 * s;
        let gap = 12.0 * s;
        let x = (w - cw) / 2.0;
        let y0 = (h - (3.0 * ch + 2.0 * gap)) / 2.0 + 24.0 * s;
        [
            [x, y0, cw, ch],
            [x, y0 + ch + gap, cw, ch],
            [x, y0 + 2.0 * (ch + gap), cw, ch],
        ]
    } else {
        let gap = 12.0 * s;
        let cw = (w - 48.0 * s - 2.0 * gap) / 3.0;
        let ch = 120.0 * s;
        let x0 = 24.0 * s;
        let y = (h - ch) / 2.0 + 18.0 * s;
        [
            [x0, y, cw, ch],
            [x0 + cw + gap, y, cw, ch],
            [x0 + 2.0 * (cw + gap), y, cw, ch],
        ]
    }
}

/// How long a denied catalog tap's notice stays up (seconds).
const CATALOG_NOTICE_SECS: f32 = 1.6;

/// The CATALOG button on the stage-select beat (meta round): under
/// the stage cards, centred — the catalog's door. The painter and
/// the hit-test share this, like every button in the kit.
fn catalog_button_rect(w: f32, h: f32) -> [f32; 4] {
    let s = hud_scale(w, h);
    let rects = stage_card_rects(w, h);
    let bottom = rects.iter().fold(0.0f32, |m, r| m.max(r[1] + r[3]));
    let bw = 200.0 * s;
    let bh = 40.0 * s;
    let y = (bottom + 44.0 * s).min(h - bh - 10.0 * s);
    [(w - bw) / 2.0, y, bw, bh]
}

/// The loop selector on the stage-select beat (meta round M3,
/// META-DESIGN §6.1): a centred pill on the beat's top row, below
/// the wallet chip's line and clear of the title and cards. Its
/// left half steps the dial down, its right half up. Drawn only
/// once a loop above 1 is unlocked. The painter and the hit-tests
/// share this, like every button in the kit.
fn loop_selector_rect(w: f32, _h: f32) -> [f32; 4] {
    let s = hud_scale(w, _h);
    let bw = 210.0 * s;
    let bh = 38.0 * s;
    [(w - bw) / 2.0, 46.0 * s, bw, bh]
}

/// One tappable row of the catalog screen (meta round, META-DESIGN
/// §7.2): a weapon row (its main zone buys/equips, its ★ strip buys
/// the next tier) or an upgrade row (the whole row buys a level).
struct CatalogRow {
    rect: [f32; 4],
    star_rect: Option<[f32; 4]>,
    /// Index into the spec's catalog (weapon rows).
    entry: Option<usize>,
    /// Index into the spec's catalog (companion rows).
    companion: Option<usize>,
    /// Index into the upgrade table's rows (upgrade rows).
    upgrade: Option<usize>,
}

/// The catalog screen's layout: one list, sized for a phone —
/// stacked full-width rows in portrait, ARSENAL left and UPGRADES
/// right in landscape. The painter and the hit-test share this.
struct CatalogLayout {
    rows: Vec<CatalogRow>,
    back: [f32; 4],
    companions_at: (f32, f32),
    arsenal_at: (f32, f32),
    upgrades_at: (f32, f32),
}

fn catalog_layout(w: f32, h: f32, meta: &MetaSpec) -> CatalogLayout {
    let s = hud_scale(w, h);
    let idx_of = |kind: &str| -> Vec<usize> {
        meta.catalog
            .iter()
            .enumerate()
            .filter(|(_, e)| e.kind == kind)
            .map(|(i, _)| i)
            .collect()
    };
    let companions = idx_of("companion");
    let weapons = idx_of("weapon");
    let back_w = 180.0 * s;
    let back = [(w - back_w) / 2.0, h - 52.0 * s, back_w, 38.0 * s];
    let mut rows = Vec::new();
    // Section geometry: a header line, then its rows. Preferred
    // row heights are the M1 sizes; when the three sections do
    // not fit between the title and the BACK button (a short
    // screen), every row shrinks by one shared factor so the
    // whole catalog always stays on one screen.
    let header_h = 24.0 * s;
    let gap = 5.0 * s;
    let main_pref = 58.0 * s;
    let up_pref = 38.0 * s;
    if h >= w {
        let x = 14.0 * s;
        let cw = w - 28.0 * s;
        let top = 56.0 * s;
        let n_main = (companions.len() + weapons.len()) as f32;
        let n_up = meta.upgrades.len() as f32;
        let preferred = 3.0 * header_h + n_main * (main_pref + gap) + n_up * (up_pref + gap);
        let avail = (back[1] - 8.0 * s - top).max(preferred * 0.5);
        let f = (avail / preferred).min(1.0);
        let main_h = main_pref * f;
        let up_h = up_pref * f;
        let companions_at = (x, top);
        let mut y = top + header_h * f;
        for &ei in &companions {
            rows.push(CatalogRow {
                rect: [x, y, cw, main_h],
                star_rect: None,
                entry: None,
                companion: Some(ei),
                upgrade: None,
            });
            y += main_h + gap * f;
        }
        let arsenal_at = (x, y);
        y += header_h * f;
        for &ei in &weapons {
            rows.push(CatalogRow {
                rect: [x, y, cw, main_h],
                star_rect: Some([x + cw * 0.58, y + main_h * 0.54, cw * 0.42, main_h * 0.46]),
                entry: Some(ei),
                companion: None,
                upgrade: None,
            });
            y += main_h + gap * f;
        }
        let upgrades_at = (x, y);
        y += header_h * f;
        for ui in 0..meta.upgrades.len() {
            rows.push(CatalogRow {
                rect: [x, y, cw, up_h],
                star_rect: None,
                entry: None,
                companion: None,
                upgrade: Some(ui),
            });
            y += up_h + gap * f;
        }
        CatalogLayout {
            rows,
            back,
            companions_at,
            arsenal_at,
            upgrades_at,
        }
    } else {
        let gap_x = 14.0 * s;
        let cw = (w - 28.0 * s - gap_x) / 2.0;
        let lx = 14.0 * s;
        let rx = lx + cw + gap_x;
        let top = 54.0 * s;
        let avail = (back[1] - top - 8.0 * s).max(60.0 * s);
        // Left column: COMPANIONS over UPGRADES. Right: ARSENAL.
        let left_pref = 2.0 * header_h
            + companions.len() as f32 * (main_pref + gap)
            + meta.upgrades.len() as f32 * (up_pref + gap);
        let lf = (avail / left_pref).min(1.0);
        let right_pref = header_h + weapons.len() as f32 * (main_pref + gap);
        let rf = (avail / right_pref).min(1.0);
        let companions_at = (lx, top);
        let mut y = top + header_h * lf;
        for &ei in &companions {
            let rh = main_pref * lf;
            rows.push(CatalogRow {
                rect: [lx, y, cw, rh],
                star_rect: None,
                entry: None,
                companion: Some(ei),
                upgrade: None,
            });
            y += rh + gap * lf;
        }
        let upgrades_at = (lx, y);
        y += header_h * lf;
        for ui in 0..meta.upgrades.len() {
            let rh = up_pref * lf;
            rows.push(CatalogRow {
                rect: [lx, y, cw, rh],
                star_rect: None,
                entry: None,
                companion: None,
                upgrade: Some(ui),
            });
            y += rh + gap * lf;
        }
        let arsenal_at = (rx, top);
        let mut y = top + header_h * rf;
        for &ei in &weapons {
            let rh = main_pref * rf;
            rows.push(CatalogRow {
                rect: [rx, y, cw, rh],
                star_rect: Some([rx + cw * 0.56, y + rh * 0.54, cw * 0.44, rh * 0.46]),
                entry: Some(ei),
                companion: None,
                upgrade: None,
            });
            y += rh + gap * rf;
        }
        CatalogLayout {
            rows,
            back,
            companions_at,
            arsenal_at,
            upgrades_at,
        }
    }
}

/// The ★ glyphs of a tier: filled stars owned, hollow ones not
/// ("★★☆" at tier 2). The glyphs are in the HUD fonts (hud_lint's
/// marker set carries both).
fn star_glyphs(tier: u32) -> String {
    let tier = tier.min(3);
    format!(
        "{}{}",
        "★".repeat(tier as usize),
        "☆".repeat(3 - tier as usize)
    )
}

/// A bonus as the catalog prints it: whole percents without a
/// decimal, fractional ones with one ("+9%", "+1.5%").
fn bonus_pct(bonus: f32) -> String {
    let pct = bonus * 100.0;
    if (pct - pct.round()).abs() < 0.05 {
        format!("+{}%", pct.round() as i32)
    } else {
        format!("+{pct:.1}%")
    }
}

/// What a timed mission asks for: the run's recurring goal posts
/// (Saka's proposal, 2026-11-16 — a small mountain to climb every
/// minute or so, against the mid-run flat).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum MissionKind {
    /// Kill so many of anything before the clock runs out.
    Slay,
    /// Kill so many of one crowd kind.
    KindSlay,
    /// Kill so many with the ultimate while it turns.
    UltSlay,
}

/// A timed mission in flight: a kill quota and the clock it races.
/// The clock holds while a boss is up (the fight is its own goal),
/// so a mission and a boss never compete for the same seconds.
#[derive(Clone, Copy, Debug)]
struct Mission {
    kind: MissionKind,
    /// The crowd kind a [`MissionKind::KindSlay`] hunts (an
    /// [`ENEMY_KINDS`] index); the other kinds ignore it.
    target_kind: usize,
    /// Kills still owed.
    left: u32,
    /// Kills the mission asked for (the readout's denominator).
    total: u32,
    /// Seconds left on the clock.
    secs: f32,
    /// Seconds the clock started with (the bar's denominator).
    total_secs: f32,
}

/// The first mission lands this far into a run (stage-clock
/// seconds): early enough to teach the loop before the first boss.
const MISSION_FIRST_SECS: f32 = 35.0;
/// How long the mission-start banner holds (s): long enough to
/// register mid-fight, short enough not to cover the fight.
const MISSION_BANNER_SECS: f32 = 2.0;
/// How long the mission-failure banner holds (s).
const MISSION_FAIL_BANNER_SECS: f32 = 1.2;
/// After a mission ends (either way), the next one waits this
/// long: the run breathes between goal posts.
const MISSION_GAP_SECS: f32 = 60.0;
/// The clock on a plain slay mission (s).
const MISSION_SLAY_SECS: f32 = 25.0;
/// The clock on a kind hunt (s): the prey has to be found, not
/// just met.
const MISSION_KIND_SECS: f32 = 30.0;
/// The clock on an ult mission (s): charge what is missing, then
/// spend it.
const MISSION_ULT_SECS: f32 = 30.0;
/// Kills an ult mission asks for: one cast measured 12-15 kills,
/// so 8 is a cast that lands in a crowd, not a perfect one.
const MISSION_ULT_TARGET: u32 = 8;
/// An ult mission is only offered at or above this gauge: below
/// it the clock could run out before the button even lights.
const MISSION_ULT_GAUGE_MIN: f32 = 50.0;

/// Kills a slay mission asks for at `tier`: the field thickens as
/// the ladder climbs, so the quota climbs with it.
fn mission_slay_target(tier: usize) -> u32 {
    14 + 3 * tier as u32
}

/// Kills a kind hunt asks for at `tier`.
fn mission_kind_target(tier: usize) -> u32 {
    5 + tier as u32
}

/// How a hunted kind reads on the HUD (the kinds' own names are
/// asset ids, not display text).
fn kind_mission_name(kind: usize) -> &'static str {
    match kind {
        KIND_COP => "COP ZOMBIES",
        KIND_WAR => "WAR ZOMBIES",
        KIND_GIRL => "GIRL ZOMBIES",
        KIND_DERRICK => "DERRICKS",
        KIND_JILL => "JILLS",
        KIND_SURVIVOR => "SURVIVORS",
        KIND_GOBLIN => "GOBLINS",
        _ => "ZOMBIES",
    }
}

impl Mission {
    /// The banner line: what the mission wants, in one breath.
    fn objective(&self) -> String {
        match self.kind {
            MissionKind::Slay => format!(
                "MISSION: SLAY {} IN {}s",
                self.total, self.total_secs as u32
            ),
            MissionKind::KindSlay => format!(
                "MISSION: SLAY {} {} IN {}s",
                self.total,
                kind_mission_name(self.target_kind),
                self.total_secs as u32
            ),
            MissionKind::UltSlay => format!(
                "MISSION: SLAY {} WITH THE ULT IN {}s",
                self.total, self.total_secs as u32
            ),
        }
    }

    /// The start banner's objective line: what is owed and how
    /// long is left, in the standing readout's shorthand.
    fn banner_objective(&self) -> String {
        match self.kind {
            MissionKind::Slay => {
                format!("SLAY {} - {}s", self.total, self.total_secs as u32)
            }
            MissionKind::KindSlay => format!(
                "HUNT {} x{} - {}s",
                kind_mission_name(self.target_kind),
                self.total,
                self.total_secs as u32
            ),
            MissionKind::UltSlay => {
                format!("ULT SLAY {} - {}s", self.total, self.total_secs as u32)
            }
        }
    }

    /// The standing readout while the clock runs: how much is
    /// done, and how long is left.
    fn progress(&self) -> String {
        let done = self.total - self.left;
        match self.kind {
            MissionKind::KindSlay => format!(
                "{} {}/{} - {}s",
                kind_mission_name(self.target_kind),
                done,
                self.total,
                self.secs.ceil() as u32
            ),
            _ => format!(
                "SLAY {}/{} - {}s",
                done,
                self.total,
                self.secs.ceil() as u32
            ),
        }
    }
}

// ---------------------------------------------------------------------------
// Enemy kinds and spawn tiers (enemy design memo §1–§2). One row per
// kind, one row per tier; both tables are pinned by tests.
// ---------------------------------------------------------------------------

pub const KIND_COP: usize = 0;
pub const KIND_WAR: usize = 1;
pub const KIND_GIRL: usize = 2;
pub const KIND_DERRICK: usize = 3;
pub const KIND_JILL: usize = 4;
pub const KIND_SURVIVOR: usize = 5;
pub const KIND_GOBLIN: usize = 6;
pub const KIND_PARASITE: usize = 7;
pub const KIND_VEGAS: usize = 8;
pub const KIND_BRUTE: usize = 9;

/// Kind rolls draw from their own stream (same rule as drops): the
/// spawn-position sequence on `rng` must not shift when the roster or
/// the tier table changes.
const KIND_SEED_XOR: u32 = 0x5EED_0002;
const AMBIENT_SEED_XOR: u32 = 0x5EED_0007;
/// The hero's post-hit invulnerability (s) — combat's `invuln_on_hit`.
const HERO_INVULN_SECS: f32 = 0.7;
/// The hero's base max HP, before VITALITY grows it.
const HERO_HP: f32 = 100.0;
/// How long a landed enemy blow reddens the screen edges (s).
const HURT_FLASH_SECS: f32 = 0.3;
/// A telegraphed grab stays live this long (s) once the windup ends.
const GRAB_ACTIVE_SECS: f32 = 0.08;
/// …and the attacker is committed for this long afterwards (s).
const GRAB_RECOVER_SECS: f32 = 0.45;
/// A poise pool left short refills after this long with no hit taken
/// and the hero at least `POISE_REFILL_RANGE` away (memo §3.2).
const POISE_REFILL_SECS: f32 = 4.0;
const POISE_REFILL_RANGE: f32 = 6.0;

/// One enemy kind: the row a crowd body is rolled from. Body stats,
/// its contact grab, its score and its look all live here.
#[derive(Clone, Copy)]
pub struct EnemyKind {
    /// Pose character id: `assets/models/poses/<id>_<pose>.glb`, and
    /// the name state JSON reports.
    pub id: &'static str,
    /// Model height (m): the pose bake's target height, and the scale
    /// base when the kind has to wear another kind's poses.
    pub height: f32,
    /// Hurt cylinder (m). `hurt_height` stays ≥ 1.2 for every kind so
    /// bolts flying at chest height (y ≈ 1.1) cannot pass overhead.
    pub hurt_radius: f32,
    pub hurt_height: f32,
    pub hp: f32,
    /// Pace on the base crowd speed (`spec.zombie_speed` × this). The
    /// hero (5.4 m/s) outruns every row.
    pub speed_x: f32,
    /// Knockback divisor: heavies barely move.
    pub mass: f32,
    /// 0 = no poise (every landed hit flinches); above 0 the body
    /// shrugs blows off until the pool breaks, then goes down for
    /// `down_secs`.
    pub poise: f32,
    /// Ailment duration shaved off (0..1) before affinity scaling.
    pub status_resist: f32,
    /// Seconds a poise break / launching blow keeps this kind down.
    pub down_secs: f32,
    /// Per-spawn pace jitter range.
    pub pace: (f32, f32),
    /// Score points the kill pays (kills are counted separately).
    pub score: u32,
    /// Elite kinds (parasite, brute): bigger loot, capped per tier.
    pub elite: bool,
    /// The heavy kind (big_vegas): belly-push grab, capped per tier.
    pub heavy: bool,
    /// Per-element damage / status-time multipliers.
    pub affinity: Affinity,
    /// The contact grab: it starts within this range (m)…
    pub grab_range: f32,
    /// …winds up for this long (s) — the tell the pose shows…
    pub grab_windup: f32,
    /// …then this sector lands. Its radius reaches a sidestepping hero
    /// less far than `grab_range` does: the windup is dodgeable.
    pub grab_def: AttackDef,
    /// Seconds before the same body may grab again; the body's slow
    /// stretches it, like it stretches the windup.
    pub grab_cooldown: f32,
    /// Colour multiplier worn when this kind's own poses are not baked
    /// and it falls back to the base kind's set.
    pub tint: [f32; 3],
}

const fn aff(damage: [f32; 4], status: [f32; 4]) -> Affinity {
    Affinity { damage, status }
}

/// The standard grab sector every normal kind shares, at `damage`.
const fn grab(damage: f32) -> AttackDef {
    AttackDef {
        knockback: 3.0,
        hitstop: 0.0,
        hitstun: 0.12,
        poise_damage: 5.0,
        ..AttackDef::sector(0.80, 60.0, damage)
    }
}

