/// The inter-attack gap （間） by phase (design §2.2).
fn boss_gap(phase: usize) -> f32 {
    [0.9, 0.7, 0.5][phase.min(2)]
}

/// The late-phase walk speed's first phase: Warrok quickens from P2,
/// the other two from P3 (design §2.1).
fn boss_late_phase(which: usize) -> usize {
    if which == BOSS_WARROK {
        1
    } else {
        2
    }
}

/// One boss's baked move set. Attack clips are registered with their
/// speed set so the measured strike frame lands exactly at the
/// windup's end (the strike frame was measured off the baked clips at
/// 240 Hz, the same pass that timed the hero's swings).
fn boss_moves(which: usize) -> MoveSet {
    let mut moves = std::collections::BTreeMap::new();
    let loop_move = |clip: &str| Move {
        clip: clip.into(),
        secs: 0.0,
        ..Move::default()
    };
    moves.insert("idle".into(), loop_move("idle"));
    moves.insert("walk".into(), loop_move("walk"));
    if which != BOSS_HULK {
        moves.insert("run".into(), loop_move("run"));
    }
    let shot = |clip: &'static str, clip_secs: f32, game_secs: f32, cue_game: f32| Move {
        clip: clip.into(),
        speed: clip_secs / game_secs,
        secs: clip_secs,
        fade: 0.08,
        hit_at: Some(cue_game * (clip_secs / game_secs)),
        hold: false,
    };
    let one = |clip: &'static str, clip_secs: f32, game_secs: f32| Move {
        clip: clip.into(),
        speed: clip_secs / game_secs,
        secs: clip_secs,
        fade: 0.08,
        hit_at: None,
        hold: false,
    };
    match which {
        BOSS_MUTANT => {
            moves.insert(
                "attack1".into(),
                shot("attack1", 2.7, 2.7 * (0.70 / 1.258), 0.70),
            );
            moves.insert(
                "attack2".into(),
                shot("attack2", 1.1333, 1.1333 * (0.60 / 0.326), 0.60),
            );
            // The leap: the slam frame lands as the boss touches down,
            // at windup + air.
            moves.insert(
                "attack3".into(),
                shot("attack3", 0.6333, 0.6333 * (1.40 / 0.608), 1.40),
            );
            moves.insert("attack_heavy".into(), one("run", 0.9, 0.5));
            moves.insert("cast".into(), one("cast", 5.4333, 2.47));
            moves.insert("spawn".into(), one("spawn", 4.7, BOSS_SPAWN_SECS));
        }
        BOSS_HULK => {
            moves.insert(
                "attack1".into(),
                shot("attack1", 2.7, 2.7 * (0.75 / 1.262), 0.75),
            );
            moves.insert(
                "attack2".into(),
                shot("attack2", 1.1333, 1.1333 * (0.70 / 0.326), 0.70),
            );
            moves.insert(
                "attack3".into(),
                shot("attack3", 0.6333, 0.6333 * (0.70 / 0.612), 0.70),
            );
            // The toss throws with the punch clip, slower.
            moves.insert(
                "shoot".into(),
                shot("attack2", 1.1333, 1.1333 * (0.80 / 0.326), 0.80),
            );
            moves.insert("cast".into(), one("cast", 5.4333, 2.47));
            moves.insert("spawn".into(), one("spawn", 4.7, BOSS_SPAWN_SECS));
        }
        _ => {
            moves.insert(
                "attack1".into(),
                shot("attack1", 2.7, 2.7 * (0.85 / 1.262), 0.85),
            );
            // The bite: the lunge's snap lands at 3.362 s of a slow
            // stalk — played fast, so the windup reads as a crouch.
            moves.insert(
                "attack2".into(),
                shot("attack2", 4.2, 4.2 * (0.70 / 3.362), 0.70),
            );
            moves.insert(
                "attack3".into(),
                shot("attack3", 0.6333, 0.6333 * (0.90 / 0.608), 0.90),
            );
            moves.insert("attack_heavy".into(), one("run", 0.9, 0.5));
            moves.insert("cast".into(), one("cast", 2.8333, 1.5));
            moves.insert("spawn".into(), one("spawn", 5.4333, BOSS_SPAWN_SECS));
        }
    }
    let def = &BOSSES[which];
    moves.insert(
        "die".into(),
        Move {
            clip: "die".into(),
            speed: 4.6333 / 2.5,
            secs: 4.6333,
            fade: 0.08,
            hit_at: None,
            hold: true,
        },
    );
    moves.insert(
        "hit_fly".into(),
        Move {
            clip: "hit_fly".into(),
            speed: 3.7333 / def.down_secs,
            secs: 3.7333,
            fade: 0.05,
            hit_at: None,
            hold: false,
        },
    );
    moves.insert(
        "hit".into(),
        Move {
            clip: "hit_fly".into(),
            speed: 1.0,
            secs: 3.7333,
            fade: 0.05,
            hit_at: None,
            hold: false,
        },
    );
    MoveSet {
        moves,
        walk_from: 0.15,
        run_from: if which == BOSS_HULK {
            f32::INFINITY
        } else if which == BOSS_WARROK {
            1.9
        } else {
            2.3
        },
        stride: match which {
            BOSS_MUTANT => 1.9,
            BOSS_HULK => 1.6,
            _ => 1.7,
        },
    }
}

/// One ground-warning disc (design §2.6), appended to the doc.
fn tele_disc(doc: &mut WorldDoc, n: &mut usize, cx: f32, cz: f32, radius: f32, em: f32) {
    doc.props.push(prop(
        &format!("telegraph-{}", *n),
        "cylinder",
        "telegraph",
        [cx, 0.05, cz],
        [radius * 2.0, 0.06, radius * 2.0],
        [255, 64, 40],
        em,
        0.9,
        0.0,
    ));
    *n += 1;
}

/// One ground-warning fan (design §2.6): a wedge of thin boxes around
/// the facing, each segment stretched along its own ray.
fn tele_fan(
    doc: &mut WorldDoc,
    n: &mut usize,
    c: (f32, f32),
    yaw: f32,
    half: f32,
    radius: f32,
    em: f32,
) {
    let (cx, cz) = c;
    let segs = 7;
    for k in 0..segs {
        let a0 = yaw - half + 2.0 * half * (k as f32 / segs as f32);
        let a1 = yaw - half + 2.0 * half * ((k + 1) as f32 / segs as f32);
        let am = (a0 + a1) / 2.0;
        let wdt = 2.0 * radius * ((a1 - a0) / 2.0).tan() * 1.12;
        let mut p = prop(
            &format!("telegraph-{}", *n),
            "box",
            "telegraph",
            [
                cx + am.sin() * radius * 0.5,
                0.05,
                cz + am.cos() * radius * 0.5,
            ],
            [wdt, 0.06, radius],
            [255, 64, 40],
            em,
            0.9,
            0.0,
        );
        p.yaw = am;
        doc.props.push(p);
        *n += 1;
    }
}

/// One ground-warning band (design §2.6): a flat strip from one point
/// to another — a charge's lane, a toss's line.
fn tele_band(doc: &mut WorldDoc, n: &mut usize, a: (f32, f32), b: (f32, f32), width: f32, em: f32) {
    let (x0, z0) = a;
    let (x1, z1) = b;
    let (dx, dz) = (x1 - x0, z1 - z0);
    let len = dx.hypot(dz);
    if len < 0.1 {
        return;
    }
    let mut p = prop(
        &format!("telegraph-{}", *n),
        "box",
        "telegraph",
        [(x0 + x1) / 2.0, 0.05, (z0 + z1) / 2.0],
        [width, 0.06, len],
        [255, 64, 40],
        em,
        0.9,
        0.0,
    );
    p.yaw = dx.atan2(dz);
    doc.props.push(p);
    *n += 1;
}

/// The cue name for a combo stage's swing (0-based chain depth,
/// 0..=6 — depth 6 is the spin finisher; past the table it clamps
/// to the last). Every depth has its own voice: the 2026-11-14
/// device check on the Mixamo build called the combo out — \"all three
/// swings sound the same\". The motion round's depths 4-7 reuse the
/// shipped files at fresh rates.
fn swing_cue(stage: usize) -> &'static str {
    [
        "swing1", "swing2", "swing3", "swing4", "swing5", "swing6", "swing7",
    ][stage.min(6)]
}

/// The cue name for a combo stage's connect (0-based chain depth).
fn melee_hit_cue(stage: usize) -> &'static str {
    ["hit1", "hit2", "hit3", "hit4", "hit5", "hit6", "hit7"][stage.min(6)]
}

/// The cue name for releasing a bolt at a charge tier: the bigger the
/// charge, the lower and louder the release.
fn cast_cue(tier: usize) -> &'static str {
    ["cast0", "cast1", "cast2"][tier.min(2)]
}

/// The cue name for a burst of this blast radius, or `None` when the
/// bolt does not burst. The neutral ladder's radii are 0 / 1.2 / 2.3;
/// the cue follows the radius, whichever spell made it.
fn blast_cue(blast: f32) -> Option<&'static str> {
    if blast <= 0.0 {
        None
    } else if blast < 2.0 {
        Some("blast1")
    } else {
        Some("blast2")
    }
}

/// The quiet blip when a held charge climbs into a tier (1 or 2), so the
/// ladder is audible as well as visible.
fn charge_cue(tier: usize) -> Option<&'static str> {
    match tier {
        1 => Some("charge1"),
        2 => Some("charge2"),
        _ => None,
    }
}

/// The music table's names (see `default_audio`): the stage tracks
/// alternate by run, the boss track plays only while a boss is up.
/// The shells map a name to its own table entry; unknown names keep
/// the plain `bgm` entry.
const TRACK_MAIN: &str = "bgm";
const TRACK_ALT: &str = "bgm_alt";
const TRACK_BOSS: &str = "bgm_boss";
/// A music switch rides the mixer's own fades: the old track fades
/// out over this span, then the new one fades in over the same span.
const MUSIC_FADE: f32 = 0.45;

fn default_audio() -> Value {
    let sfx = "assets/audio/oga-retro-synth-sfx/";
    let cue =
        |f: &str, v: f64, r: f64| json!({"file": format!("{sfx}{f}"), "volume": v, "rate": r});
    json!({
        "enabled": true,
        "master": 0.8,
        "sfx_volume": 1.0,
        "bgm_volume": 0.5,
        // This kit's own track: the survivor kits share Flowerbed Fields,
        // and the 2026-11-14 device check asked why all three games
        // sound the same. Harlem Night is an original hard-bop / funk
        // loop made for this game's night-city stage
        // (assets/audio/city_action/).
        "bgm": {"file": "assets/audio/city_action/harlem_night.mp3", "volume": 0.6, "fade_secs": 0.5},
        // Two more original loops from the same synth bench: the
        // second stage track (runs alternate, see `confirm`) and the
        // boss track (a boss swaps the music, its fall swaps back).
        "bgm_alt": {"file": "assets/audio/city_action/lenox_after_hours.mp3", "volume": 0.6, "fade_secs": 0.5},
        "bgm_boss": {"file": "assets/audio/city_action/boss_stomp.mp3", "volume": 0.65, "fade_secs": 0.5},
        "sfx": {
            // One voice per combo stage. The whoosh climbs in rate and
            // weight down the combo; stage 3 swaps the file for a bigger
            // sweep. Connects drop in rate (heavier) and rise in volume,
            // stage 3 at full weight — the finisher.
            "swing1": cue("power_up_02.wav", 0.32, 1.3),
            "swing2": cue("power_up_02.wav", 0.36, 1.55),
            "swing3": cue("power_up_04.wav", 0.46, 1.45),
            "hit1": cue("retro_explosion_02.wav", 0.28, 1.5),
            "hit2": cue("retro_explosion_02.wav", 0.34, 1.3),
            "hit3": cue("retro_explosion_02.wav", 0.48, 1.05),
            // Chain depths 4-7 (motion round): the same shelf, new
            // rates — the whoosh climbs, the connect drops.
            "swing4": cue("power_up_02.wav", 0.34, 1.75),
            "swing5": cue("power_up_02.wav", 0.36, 1.9),
            "swing6": cue("power_up_04.wav", 0.48, 1.65),
            "swing7": cue("power_up_04.wav", 0.55, 1.2),
            "hit4": cue("retro_explosion_02.wav", 0.36, 1.2),
            "hit5": cue("retro_explosion_02.wav", 0.44, 1.1),
            "hit6": cue("retro_explosion_02.wav", 0.5, 0.95),
            "hit7": cue("retro_explosion_02.wav", 0.6, 0.8),
            // The bolt's own small tick when it lands on a single body
            // (a charged burst speaks with blast1 / blast2 instead).
            "hit": cue("retro_explosion_02.wav", 0.3, 1.4),
            // Charged magic: the release drops in rate and rises in
            // volume with the tier, and the burst follows it down.
            "cast0": cue("shot_01.wav", 0.38, 1.25),
            "cast1": cue("power_up_02.wav", 0.5, 0.8),
            "cast2": cue("power_up_04.wav", 0.62, 0.62),
            "blast1": cue("retro_explosion_02.wav", 0.42, 0.9),
            "blast2": cue("retro_explosion_02.wav", 0.6, 0.62),
            // Quiet rungs while the charge climbs.
            "charge1": cue("power_up_02.wav", 0.22, 1.05),
            "charge2": cue("power_up_04.wav", 0.28, 1.0),
            // Pickups (design §3.8): a heal is a low warm blip, a rune
            // gets the big power-up (it is the run's unlock moment).
            "pickup_heal": cue("power_up_02.wav", 0.32, 0.75),
            "pickup_rune": cue("power_up_04.wav", 0.42, 1.15),
            // The boss round's voices, from the same shelf: a roar is
            // the big power-up dragged low, a leap's landing the
            // explosion at half rate.
            "roar": cue("power_up_04.wav", 0.7, 0.45),
            "stomp": cue("retro_explosion_02.wav", 0.7, 0.55),
            "go": {"file": "assets/audio/kenney-interface-sounds/confirmation_001.wav", "volume": 0.7, "rate": 1.0},
            // The ult-ready chime: an original two-bell ping from
            // this kit's own shelf, struck once when the gauge tops
            // out (the chime watch in step_sim) — the audible half
            // of the button lighting up.
            "ult_ready": {"file": "assets/audio/city_action/ult_ready.mp3", "volume": 0.55, "rate": 1.0},
            // The bg streets' ambience (2026-11-18): an original
            // synthesized wind + low-drone loop from this kit's own
            // shelf, cued as a one-shot and re-cued just before it
            // ends (see `step_atmo`) — a poor man's second channel
            // that layers it under the BGM in bg mode only. Being
            // an sfx entry, it is fetched and decoded at boot like
            // every other cue (no lazy decode, first-occurrence
            // rule). The default game never cues it.
            "ambience": {"file": "assets/audio/city_action/night_wind.mp3", "volume": 0.42, "rate": 1.0}
        }
    })
}

/// Circle vs axis-aligned boxes, the `stealth.rs` push-out: if the circle
/// reaches into the box (expanded by the radius), leave along the axis of
/// least penetration. A few passes settle corners.
fn push_out_of_blocks(x: &mut f32, z: &mut f32, r: f32) {
    fn push_one(x: &mut f32, z: &mut f32, r: f32, cx: f32, cz: f32, hx: f32, hz: f32) {
        let dx = *x - cx;
        let dz = *z - cz;
        let px = hx + r - dx.abs();
        let pz = hz + r - dz.abs();
        if px > 0.0 && pz > 0.0 {
            if px < pz {
                *x = cx + (hx + r) * if dx >= 0.0 { 1.0 } else { -1.0 };
            } else {
                *z = cz + (hz + r) * if dz >= 0.0 { 1.0 } else { -1.0 };
            }
        }
    }
    for _ in 0..3 {
        for &(cx, cz, hx, hz, _) in BLOCKS.iter() {
            push_one(x, z, r, cx, cz, hx, hz);
        }
        for &(cx, cz, hx, hz) in PROP_BOXES.iter() {
            push_one(x, z, r, cx, cz, hx, hz);
        }
    }
}

/// Is the point inside any building block, expanded by `r`? (Bolt impacts.)
fn point_in_blocks(x: f32, z: f32, r: f32) -> bool {
    BLOCKS
        .iter()
        .any(|&(cx, cz, hx, hz, _)| (x - cx).abs() <= hx + r && (z - cz).abs() <= hz + r)
}

/// Does the segment (x0, z0)-(x1, z1) cross any building block? Aim assist
/// refuses targets behind a wall (slab test per block).
fn segment_blocked(x0: f32, z0: f32, x1: f32, z1: f32) -> bool {
    let (dx, dz) = (x1 - x0, z1 - z0);
    BLOCKS.iter().any(|&(cx, cz, hx, hz, _)| {
        let (mut lo, mut hi) = (0.0f32, 1.0f32);
        for (o, d, c, h) in [(x0, dx, cx, hx), (z0, dz, cz, hz)] {
            if d.abs() < 1e-6 {
                if (o - c).abs() > h {
                    return false;
                }
            } else {
                let (mut a, mut b) = ((c - h - o) / d, (c + h - o) / d);
                if a > b {
                    std::mem::swap(&mut a, &mut b);
                }
                lo = lo.max(a);
                hi = hi.min(b);
                if lo > hi {
                    return false;
                }
            }
        }
        true
    })
}

/// Does the 3D segment p0-p1 cross block `i`'s box, drawn `top`
/// high (footprint grown by `margin`, from the ground up)? The
/// camera cutaway's sight test: `segment_blocked` with a y slab.
fn segment_hits_block_h(p0: [f32; 3], p1: [f32; 3], i: usize, top: f32, margin: f32) -> bool {
    let (cx, cz, hx, hz, _) = BLOCKS[i];
    let (dx, dy, dz) = (p1[0] - p0[0], p1[1] - p0[1], p1[2] - p0[2]);
    let (mut lo, mut hi) = (0.0f32, 1.0f32);
    for (o, d, c, h) in [
        (p0[0], dx, cx, hx + margin),
        (p0[1], dy, top * 0.5, top * 0.5),
        (p0[2], dz, cz, hz + margin),
    ] {
        if d.abs() < 1e-6 {
            if (o - c).abs() > h {
                return false;
            }
        } else {
            let (mut a, mut b) = ((c - h - o) / d, (c + h - o) / d);
            if a > b {
                std::mem::swap(&mut a, &mut b);
            }
            lo = lo.max(a);
            hi = hi.min(b);
            if lo > hi {
                return false;
            }
        }
    }
    true
}

/// [`segment_hits_block_h`] at the block's full table height.
fn segment_hits_block3(p0: [f32; 3], p1: [f32; 3], i: usize, margin: f32) -> bool {
    segment_hits_block_h(p0, p1, i, BLOCKS[i].4, margin)
}

/// The signed smallest turn from `from` to `to` (radians, -PI..=PI).
fn angle_delta(from: f32, to: f32) -> f32 {
    let mut d = (to - from) % std::f32::consts::TAU;
    if d > std::f32::consts::PI {
        d -= std::f32::consts::TAU;
    } else if d < -std::f32::consts::PI {
        d += std::f32::consts::TAU;
    }
    d
}

// --------------------------------------------------------------- combat ----

// One stage of the sword combo (design §2.6). `hit_at` is measured, not
// felt: sampled from the Mixamo clips' hand-joint trajectories on
// 2026-11-14 (peak hand speed = the blow's impact moment), as recorded in
// design §1.4. The fan is measured from the same clips: the sword tip
// reaches 1.53-1.62 m in the fast window and the blade crosses the front
// in a ~100-120 deg arc, so the KayKit-era fan (2.3-2.5 m, 130-150 deg)
// shrank to the real swing on 2026-11-14 after a device check called it
// too wide. Hitstop / knockback were strengthened the same day within
// the §2 starting-value scale after a video review found them hard to
// read (stage 3 most of all).
//
// The fan above is the *judgement*; the shipped sword meshes are bigger
// than the measured one on purpose (see the HERO_GLB note): the standard
// sword's tip reaches 1.96-2.20 m in the swing windows — meeting the
// fan's edge (radius + a zombie's hurt radius = 2.02-2.12 m) instead of
// falling ~0.4 m short of it, which is what made the hits look like they
// connected with air.
//
// The table below is the v3 design §2.3 starting values for the one
// sword. A stage is written once, here, as a function of its numbers.

/// Degrees to the radians `AttackDef` stores.
const fn deg(d: f32) -> f32 {
    d * (std::f32::consts::PI / 180.0)
}

/// One combo stage from its numbers (hitstun is 0.2 on every stage,
/// v3 design §2.3).
#[allow(clippy::too_many_arguments)]
const fn combo_stage(
    total: f32,
    hit_at: f32,
    radius: f32,
    half_deg: f32,
    damage: f32,
    knockback: f32,
    hitstop: f32,
    poise: f32,
    fly: bool,
    effect: Effect,
    step_speed: f32,
) -> ComboStage {
    ComboStage {
        total,
        hit_at,
        def: AttackDef {
            radius,
            half_angle: deg(half_deg),
            damage,
            knockback,
            hitstop,
            hitstun: 0.2,
            poise_damage: poise,
            fly,
            effect,
        },
        step_speed,
    }
}

