    #[test]
    fn bursts_and_swings_draw_rings_not_filled_discs() {
        // Device-feedback round 4 (2026-11-20): the filled discs
        // hid the hero on device — the swing's cream cylinder and
        // the bursts' pale flattened spheres. Both now draw as
        // point rings/arcs; this pins the shapes so the filled
        // discs cannot creep back.
        let mut g = playing();
        solo(&mut g, 0, 0.0, 4.0);
        g.crowd[0].pace = 0.0;
        g.crowd[0].cd_left = 999.0;
        g.start_burst();
        step_n(&mut g, 6);
        assert!(!g.blasts.is_empty(), "the burst is live");
        g.build_doc();
        assert!(
            !g.doc.props.iter().any(|p| p.id.starts_with("prop:blast-")),
            "no filled blast disc prop is drawn"
        );
        let fx = g.blasts.last().unwrap();
        let u = (fx.age / BLAST_FX_SECS).clamp(0.0, 1.0);
        let want_r = fx.radius * (0.35 + 0.65 * (1.0 - (1.0 - u) * (1.0 - u)));
        let ring = g
            .doc
            .points
            .iter()
            .find(|c| c.id == "fx:blast-ring-0")
            .expect("the burst draws its ring");
        assert!(ring.positions.len() >= 12, "the ring is a ring");
        for p in &ring.positions {
            let d = (p[0] - fx.x).hypot(p[2] - fx.z);
            assert!(
                (d - want_r).abs() < 0.05,
                "ring point at {d}, want {want_r}"
            );
            assert!((p[1] - 0.07).abs() < 1e-4, "the ring lies on the ground");
        }
        // A swing draws its arc, not the old filled cylinder.
        let mut g = playing();
        g.buttons.set_host(ActionId::Melee, true);
        g.buttons.set_host(ActionId::Melee, false);
        for _ in 0..30 {
            g.step(DT);
            if g.action == HeroAction::Swing {
                break;
            }
        }
        assert_eq!(g.action, HeroAction::Swing, "the cut is in flight");
        g.build_doc();
        assert!(
            !g.doc.props.iter().any(|p| p.id == "prop:swing"),
            "no filled swing disc prop is drawn"
        );
        let arc = g
            .doc
            .points
            .iter()
            .find(|c| c.id == "fx:swing-arc")
            .expect("the swing draws its arc");
        let stage = g.swing_timing;
        let k = (g.action_t / stage.total).clamp(0.0, 1.0);
        let want_r = 0.6 + (stage.def.radius - 0.6) * (k / 0.6);
        assert!(arc.positions.len() >= 5, "the arc is an arc");
        for p in &arc.positions {
            let (dx, dz) = (p[0] - g.hero.0, p[2] - g.hero.1);
            let d = dx.hypot(dz);
            assert!((d - want_r).abs() < 0.05, "arc point at {d}, want {want_r}");
            let a = dx.atan2(dz);
            let mut diff = (a - g.face).rem_euclid(std::f32::consts::TAU);
            if diff > std::f32::consts::PI {
                diff -= std::f32::consts::TAU;
            }
            assert!(
                diff.abs() <= stage.def.half_angle + 0.02,
                "arc point {diff} rad off the facing, fan is {}",
                stage.def.half_angle
            );
        }
    }

