    #[test]
    fn the_ready_chime_arms_once_per_fill() {
        // The chime watch: the flag sets as the gauge tops out,
        // holds while the button sits lit (it cannot ring twice),
        // and clears once the cast has spent the gauge.
        let mut g = playing();
        solo(&mut g, 0, 0.0, 4.5);
        crate::mixer::reset_mixer();
        assert!(!g.ult_ready_cued);
        g.ult_gauge = ULT_GAUGE_MAX;
        step_n(&mut g, 1);
        assert!(g.ult_ready_cued, "the fill was announced");
        step_n(&mut g, 5);
        assert!(g.ult_ready_cued, "and it does not ring again");
        let rings = oneshots().iter().filter(|s| *s == "ult_ready").count();
        assert_eq!(rings, 1, "exactly one chime for the fill");
        ult_press(&mut g);
        step_n(&mut g, 2);
        assert_eq!(g.action, HeroAction::Ult, "the press converted");
        assert!(!g.ult_ready_cued, "spent: the watch has re-armed");
    }

    #[test]
    fn the_hurt_vignette_frames_the_edges_only() {
        // The polish round: no full-screen red wash — the red
        // lives on the rim and the centre of the screen stays
        // clear, so a hit landing in a crowd no longer hides it.
        let mut g = playing();
        g.hurt_flash = HURT_FLASH_SECS;
        let list = g.hud(390, 844, false);
        let reds: Vec<&Quad> = list
            .quads
            .iter()
            .filter(|q| q.color[0] > 180 && q.color[1] < 80 && q.color[2] < 80 && q.color[3] > 0)
            .collect();
        assert!(!reds.is_empty(), "the hit still shows");
        for q in &reds {
            assert!(
                !(q.x <= 1.0 && q.y <= 1.0 && q.w >= 388.0 && q.h >= 842.0),
                "no full-screen wash: {q:?}"
            );
            // Every red quad lives in the rim: within one vignette
            // depth of the nearest edge, never wandering inward.
            let rim =
                q.x.min(q.y)
                    .min(390.0 - (q.x + q.w))
                    .min(844.0 - (q.y + q.h));
            assert!(rim <= 67.0, "the red stays in the rim: {q:?}");
        }
        // The middle of the screen carries no red at all.
        let mid = reds
            .iter()
            .any(|q| q.x < 195.0 && q.x + q.w > 195.0 && q.y < 422.0 && q.y + q.h > 422.0);
        assert!(!mid, "the centre stays clear");
    }

    #[test]
    fn the_ult_is_committed_and_refires_without_a_lockout() {
        let mut g = playing();
        solo(&mut g, 0, 0.0, 4.5);
        g.ult_gauge = ULT_GAUGE_MAX;
        ult_press(&mut g);
        step_n(&mut g, 10);
        assert_eq!(g.action, HeroAction::Ult);
        // A melee press mid-cast does not cancel it.
        g.buttons.set_host(ActionId::Melee, true);
        g.buttons.set_host(ActionId::Melee, false);
        step_n(&mut g, 10);
        assert_eq!(g.action, HeroAction::Ult, "the cast is committed");
        step_n(&mut g, 90);
        assert_eq!(g.action, HeroAction::None);
        assert_eq!(g.ults, 1);
        // No lockout sits on the button: the moment the gauge is
        // full again a press fires — the gauge is the only gate.
        g.ult_gauge = ULT_GAUGE_MAX;
        ult_press(&mut g);
        step_n(&mut g, 1);
        assert_eq!(g.action, HeroAction::Ult, "it refires at once");
        assert_eq!(g.ults, 2);
    }

    #[test]
    fn a_touch_on_the_drawn_ult_button_fires_it() {
        // The phone path (the preview pump never sends an ult): a
        // tap on the drawn ULT button, inside one step — the same
        // latch road as the drawn DODGE button.
        let mut g = playing();
        g.ult_gauge = ULT_GAUGE_MAX;
        let (w, h) = (390u32, 844u32);
        let (uc, _) = g.ult_layout(w as f32, h as f32);
        let ev = |phase| PointerEvent {
            id: 11,
            x: uc.0,
            y: uc.1,
            phase,
            pressure: 1.0,
        };
        g.touch_ev(ev(PointerPhase::Begin), w, h);
        g.touch_ev(ev(PointerPhase::End), w, h);
        step_n(&mut g, 1);
        assert_eq!(g.action, HeroAction::Ult, "the tap fired the ult");
        // Below a full gauge the same tap lands on a dark button.
        let mut g = playing();
        g.ult_gauge = ULT_GAUGE_MAX - 1.0;
        g.touch_ev(ev(PointerPhase::Begin), w, h);
        g.touch_ev(ev(PointerPhase::End), w, h);
        step_n(&mut g, 2);
        assert_eq!(g.action, HeroAction::None);
        assert_eq!(g.ults, 0);
    }

