    #[test]
    fn the_ult_button_never_overlaps_its_neighbours() {
        let g = playing();
        for (w, h) in [(390.0, 844.0), (844.0, 390.0), (1280.0, 800.0)] {
            let (uc, ur) = g.ult_layout(w, h);
            let ((hc, hr), (rc, rr)) = g.btn_layout(w, h);
            let (cc, cr) = g.chip_layout(w, h);
            let (dc, dr) = g.dodge_layout(w, h);
            let d_melee = (uc.0 - hc.0).hypot(uc.1 - hc.1);
            assert!(d_melee > ur + hr, "ult vs melee");
            let d_magic = (uc.0 - rc.0).hypot(uc.1 - rc.1);
            assert!(d_magic > ur + rr, "ult vs magic");
            let d_chip = (uc.0 - cc.0).hypot(uc.1 - cc.1);
            assert!(d_chip > ur + cr, "ult vs spell chip");
            let d_dodge = (uc.0 - dc.0).hypot(uc.1 - dc.1);
            assert!(d_dodge > ur + dr, "ult vs dodge");
        }
    }

    #[test]
    fn the_magic_atlas_is_declared_before_any_cast() {
        // First-occurrence pin for the sprite layer: a fresh game's
        // very first doc already names the atlas in every fx cloud
        // (with zero sprites), so the renderer uploads it at boot —
        // no cast can first-introduce it mid-run.
        let g = CityAction::new(CityActionSpec::default());
        let clouds: Vec<_> = g
            .doc
            .points
            .iter()
            .filter(|c| c.atlas.as_deref() == Some(MAGIC_ATLAS))
            .collect();
        assert_eq!(
            clouds.len(),
            magic_fx_spec().kinds.len(),
            "one cloud per fx kind"
        );
        assert!(clouds.iter().all(|c| c.positions.is_empty()));
    }

    #[test]
    fn a_spell_burst_writes_flipbook_sprites() {
        let mut g = playing();
        // A tier-2-radius fire burst takes the big sheet; a tier-1
        // ice burst the small one. Sparks (and smoke on the big one)
        // ride along: 1 + 10 + 3 and 1 + 7 particles.
        g.fx_blast_at(2.0, 3.0, 2.3, Element::Fire);
        g.fx_blast_at(-2.0, 3.0, 1.2, Element::Ice);
        assert_eq!(g.fx.len(), 14 + 8);
        g.build_doc();
        let cloud = |name: &str| {
            g.doc
                .points
                .iter()
                .find(|c| c.id.ends_with(name))
                .unwrap_or_else(|| panic!("cloud {name}"))
        };
        let big = cloud("fire_blast2");
        assert_eq!(big.positions.len(), 1);
        assert_eq!(big.frames.len(), 1);
        let uv = big.frames[0];
        assert!(uv[0] >= 0.0 && uv[2] <= 1.0 && uv[1] >= 0.0 && uv[3] <= 1.0);
        assert_eq!(cloud("ice_blast").positions.len(), 1);
        assert_eq!(cloud("ice_blast2").positions.len(), 0);
        assert_eq!(cloud("blast_smoke").positions.len(), 3);
    }

