    #[test]
    fn a_tap_fires_exactly_one_plain_bolt() {
        // The latch guarantee under the charge rules: a sub-step tap still
        // fires exactly one bolt, at the tier 0 (§2.7) numbers.
        let mut g = playing();
        solo(&mut g, 0, 0.0, -20.0); // far away: the bolt flies its full range
        g.buttons.set_host(ActionId::Ranged, true);
        g.buttons.set_host(ActionId::Ranged, false);
        let mut spawned = 0;
        for _ in 0..150 {
            let before = g.projectiles.len();
            g.step(DT);
            if g.projectiles.len() > before {
                spawned += 1;
                let p = g.projectiles.last().unwrap();
                assert_eq!(p.damage, 12.0, "a tap is the plain bolt");
                assert_eq!(p.radius, 0.28);
                assert_eq!(p.knockback, 2.5);
                assert_eq!(p.blast, 0.0, "a tap never bursts");
            }
        }
        assert_eq!(spawned, 1, "one tap, one bolt");
        let (_, fired, expired) = g.buttons.counts(ActionId::Ranged);
        assert_eq!((fired, expired), (1, 0));
    }

    #[test]
    fn holding_charges_and_nothing_fires_until_release() {
        let mut g = playing();
        solo(&mut g, 0, 0.0, -20.0);
        g.buttons.set_host(ActionId::Ranged, true);
        // 0.3 s of holding: a charge in progress — no cast, no bolt.
        step_n(&mut g, 18);
        assert!(g.charging, "the hold is a charge now, not a repeat");
        assert_eq!(g.action, HeroAction::None, "no cast while charging");
        assert!(g.projectiles.is_empty(), "nothing fires mid-charge");
        // Past the 0.45 s threshold the charge shows tier 1, still unfired.
        step_n(&mut g, 20);
        assert_eq!(BOLT_CHARGE.tier(g.charge_t), 1);
        assert!(g.projectiles.is_empty());
        // Release: exactly one cast, at the tier 1 numbers.
        g.buttons.set_host(ActionId::Ranged, false);
        step_n(&mut g, 1);
        assert!(!g.charging, "the release ends the charge");
        assert_eq!(g.action, HeroAction::Shoot);
        step_n(&mut g, 20);
        assert_eq!(g.projectiles.len(), 1, "one release, one bolt");
        let p = &g.projectiles[0];
        assert_eq!(p.damage, 21.0, "tier 1 damage");
        assert_eq!(p.radius, 0.45, "tier 1 radius");
        assert_eq!(p.knockback, 4.0, "tier 1 knockback");
        assert_eq!(p.blast, 1.2, "tier 1 bursts small");
    }

    #[test]
    fn a_held_charge_stamps_its_tier_crossings() {
        // Freeze instrumentation (2026-11-17): the stage-clock
        // times a charge climbs into tiers 1 and 2 stay readable
        // in the state, so a hitch felt mid-charge can be lined
        // up against the crossings afterwards.
        let mut g = playing();
        solo(&mut g, 0, 0.0, -20.0); // far off: the charge is the subject
        assert_eq!(g.state_value()["charge_tier1_at"], Value::Null);
        g.buttons.set_host(ActionId::Ranged, true);
        step_n(&mut g, 40); // past 0.45 s, short of 0.95 s
        assert!(g.charging, "the hold is still gathering");
        let t1 = g.charge_tier1_at.expect("tier 1 was crossed");
        assert!(g.charge_tier2_at.is_none(), "tier 2 not yet");
        assert!((t1 - 0.45).abs() < 0.1, "crossed at the threshold: {t1}");
        step_n(&mut g, 40); // past 0.95 s
        let t2 = g.charge_tier2_at.expect("tier 2 was crossed");
        assert!(
            t2 > t1 && (t2 - 0.95).abs() < 0.1,
            "tier 2 at its threshold: {t2}"
        );
        let v = g.state_value();
        assert_eq!(v["charge_tier1_at"], (t1 * 10.0).round() / 10.0);
        assert_eq!(v["charge_tier2_at"], (t2 * 10.0).round() / 10.0);
        g.buttons.set_host(ActionId::Ranged, false);
    }

    #[test]
    fn charge_tiers_carry_a_growing_blast() {
        // The 2026-11-14 device-check rule: charging must buy area, not
        // just damage. The tap stays single-target; tier 2's burst (2.3 m)
        // is wider than the melee fan is long.
        assert_eq!(BOLT_CHARGE.get(0).blast, 0.0);
        assert_eq!(BOLT_CHARGE.get(1).blast, 1.2);
        assert_eq!(BOLT_CHARGE.get(2).blast, 2.3);
        assert!(BOLT_CHARGE.get(2).blast > melee(0).def.radius - 0.4);
    }

    #[test]
    fn a_full_charge_blast_takes_the_whole_knot() {
        // Three zombies knotted 5 m ahead, a fourth off to the side: the
        // tier 2 bolt touches one, its burst takes the knot, the fourth
        // lives. A plain bolt would have killed exactly one.
        let mut g = playing();
        let spots = [(0.0, 1.0), (0.9, 0.6), (-0.9, 0.6), (7.0, 1.0)];
        for i in 0..MAX_CROWD {
            let bi = CityAction::body_idx(i);
            if let Some(&(x, z)) = spots.get(i) {
                g.crowd[i].parked = false;
                g.write_kind(i, KIND_COP);
                g.bodies[bi].revive(x, z);
            } else {
                g.crowd[i].parked = true;
                g.bodies[bi].state = BodyState::Dead;
            }
        }
        g.buttons.set_host(ActionId::Ranged, true);
        step_n(&mut g, 66); // 1.1 s: tier 2
        assert_eq!(BOLT_CHARGE.tier(g.charge_t), 2);
        g.buttons.set_host(ActionId::Ranged, false);
        step_n(&mut g, 90);
        assert_eq!(g.kills, 3, "the burst took the whole knot");
        let side = &g.bodies[CityAction::body_idx(3)];
        assert_eq!(side.hp, ZOMBIE_HP, "the side zombie is outside the burst");
    }

