    #[test]
    fn the_measured_fan_is_pinned() {
        // 2026-11-14: the fan and the cues are the Mixamo measurement
        // record (design §1.4 / §2.6), not tuning knobs: tip reach
        // 1.53-1.62 m in the fast window, blade crossing the front in a
        // ~100-120 deg arc. The hit_at pins below were retimed by
        // the motion round to ITS clips' measured peaks (outward
        // 0.432, inward 0.550, the flurry's first peak 0.235).
        assert_eq!(melee(0).def.radius, 1.6);
        assert_eq!(melee(1).def.radius, 1.6);
        assert_eq!(melee(2).def.radius, 1.7);
        let deg = |r: f32| r * 180.0 / std::f32::consts::PI;
        assert!((deg(melee(0).def.half_angle) - 50.0).abs() < 0.01);
        assert!((deg(melee(1).def.half_angle) - 50.0).abs() < 0.01);
        assert!((deg(melee(2).def.half_angle) - 60.0).abs() < 0.01);
        assert_eq!(melee(0).hit_at, 0.156);
        assert_eq!(melee(1).hit_at, 0.187);
        assert_eq!(melee(2).hit_at, 0.113);
        assert_eq!(BOLT_RELEASE_AT, 0.10);
    }

    #[test]
    fn cue_names_follow_the_stage_and_tier() {
        // Every combo stage swings and connects with its own cue
        // (2026-11-14 device check: "all three swings sound the same").
        assert_eq!(swing_cue(0), "swing1");
        assert_eq!(swing_cue(1), "swing2");
        assert_eq!(swing_cue(2), "swing3");
        assert_eq!(melee_hit_cue(0), "hit1");
        assert_eq!(melee_hit_cue(1), "hit2");
        assert_eq!(melee_hit_cue(2), "hit3");
        // Past the table, the deepest voice (the spin's).
        assert_eq!(swing_cue(9), "swing7");
        assert_eq!(melee_hit_cue(9), "hit7");
        // Charge tiers release with their own cue; only charged bolts
        // burst, and the rung blips start at tier 1.
        assert_eq!(cast_cue(0), "cast0");
        assert_eq!(cast_cue(1), "cast1");
        assert_eq!(cast_cue(2), "cast2");
        assert_eq!(blast_cue(BOLT_CHARGE.get(0).blast), None);
        assert_eq!(blast_cue(BOLT_CHARGE.get(1).blast), Some("blast1"));
        assert_eq!(blast_cue(BOLT_CHARGE.get(2).blast), Some("blast2"));
        assert_eq!(charge_cue(0), None);
        assert_eq!(charge_cue(1), Some("charge1"));
        assert_eq!(charge_cue(2), Some("charge2"));
    }

    #[test]
    fn the_audio_table_gives_every_stage_and_tier_its_own_voice() {
        let sfx = default_audio()["sfx"].clone();
        let voice = |name: &str| {
            let c = &sfx[name];
            assert!(c.is_object(), "cue {name} is defined");
            (
                c["file"].as_str().unwrap().to_string(),
                c["rate"].as_f64().unwrap(),
                c["volume"].as_f64().unwrap(),
            )
        };
        // No two stages share a swing voice (file + rate + volume).
        let swings = [voice("swing1"), voice("swing2"), voice("swing3")];
        for i in 0..3 {
            for j in (i + 1)..3 {
                assert_ne!(swings[i], swings[j], "stages share a swing voice");
            }
        }
        // Connects get heavier down the combo: rate down, volume up.
        let hits = [voice("hit1"), voice("hit2"), voice("hit3")];
        assert!(
            hits[0].1 > hits[1].1 && hits[1].1 > hits[2].1,
            "hit rates fall"
        );
        assert!(
            hits[0].2 < hits[1].2 && hits[1].2 < hits[2].2,
            "hit volumes rise"
        );
        // The release deepens with the tier; the burst follows it down.
        let casts = [voice("cast0"), voice("cast1"), voice("cast2")];
        assert!(casts[0].1 > casts[1].1 && casts[1].1 > casts[2].1);
        assert!(casts[0].2 < casts[1].2 && casts[1].2 < casts[2].2);
        let (b1, b2) = (voice("blast1"), voice("blast2"));
        assert!(
            b2.1 < b1.1 && b2.2 > b1.2,
            "the bigger burst is lower and louder"
        );
        // Every other cue the kit can fire is in the table too.
        for name in ["hit", "go", "charge1", "charge2", "ult_ready"] {
            voice(name);
        }
    }

