    #[test]
    fn spell_tables_are_pinned() {
        // (hold, damage, radius, knockback, blast, effect) per tier,
        // straight from the v3 design §1.5 tables.
        type SpellRow = (f32, f32, f32, f32, f32, Effect);
        let want: [[SpellRow; 3]; 4] = [
            [
                (0.0, 12.0, 0.28, 2.5, 0.0, Effect::None),
                (0.45, 21.0, 0.45, 4.0, 1.2, Effect::None),
                (0.95, 34.0, 0.66, 6.0, 2.3, Effect::None),
            ],
            [
                (
                    0.0,
                    9.0,
                    0.28,
                    2.0,
                    0.0,
                    Effect::Burn {
                        dps: 3.0,
                        secs: 2.0,
                    },
                ),
                (
                    0.45,
                    16.0,
                    0.45,
                    3.0,
                    1.2,
                    Effect::Burn {
                        dps: 5.0,
                        secs: 3.0,
                    },
                ),
                (
                    0.95,
                    26.0,
                    0.66,
                    5.0,
                    2.3,
                    Effect::Burn {
                        dps: 6.0,
                        secs: 4.0,
                    },
                ),
            ],
            [
                (
                    0.0,
                    9.0,
                    0.28,
                    1.5,
                    0.0,
                    Effect::Slow {
                        factor: 0.70,
                        secs: 1.5,
                    },
                ),
                (
                    0.45,
                    16.0,
                    0.45,
                    2.5,
                    1.2,
                    Effect::Slow {
                        factor: 0.55,
                        secs: 2.5,
                    },
                ),
                (
                    0.95,
                    25.0,
                    0.66,
                    3.5,
                    2.6,
                    Effect::Slow {
                        factor: 0.40,
                        secs: 3.5,
                    },
                ),
            ],
            [
                (
                    0.0,
                    10.0,
                    0.28,
                    2.0,
                    0.0,
                    Effect::Chain {
                        jumps: 1,
                        range: 3.0,
                        scale: 0.6,
                    },
                ),
                (
                    0.45,
                    17.0,
                    0.45,
                    3.0,
                    0.9,
                    Effect::Chain {
                        jumps: 2,
                        range: 3.5,
                        scale: 0.6,
                    },
                ),
                (
                    0.95,
                    28.0,
                    0.66,
                    5.0,
                    1.6,
                    Effect::Chain {
                        jumps: 4,
                        range: 4.0,
                        scale: 0.6,
                    },
                ),
            ],
        ];
        for (e, ladder) in SPELLS.iter().enumerate() {
            assert_eq!(Element::ALL[e].index(), e, "table order is element order");
            for (tier, &(hold, dmg, radius, kb, blast, effect)) in want[e].iter().enumerate() {
                let got = ladder.get(tier);
                assert_eq!(got.hold_secs, hold, "spell {e} tier {tier} hold");
                assert_eq!(got.damage, dmg, "spell {e} tier {tier} damage");
                assert_eq!(got.radius, radius, "spell {e} tier {tier} radius");
                assert_eq!(got.knockback, kb, "spell {e} tier {tier} knockback");
                assert_eq!(got.blast, blast, "spell {e} tier {tier} blast");
                assert_eq!(got.effect, effect, "spell {e} tier {tier} effect");
            }
        }
    }

    #[test]
    fn every_spell_ladder_grows() {
        // The §1.5 invariants, all four ladders: every number strictly
        // grows with the tier, the tap never bursts, effects strengthen,
        // and the hold rhythm is shared.
        for (e, ladder) in SPELLS.iter().enumerate() {
            assert_eq!(ladder.len(), 3);
            assert_eq!(ladder.get(0).blast, 0.0, "spell {e}: the tap never bursts");
            for w in 0..2 {
                let (a, b) = (ladder.get(w), ladder.get(w + 1));
                assert!(b.damage > a.damage, "spell {e} damage grows");
                assert!(b.radius > a.radius, "spell {e} radius grows");
                assert!(b.knockback > a.knockback, "spell {e} knockback grows");
                assert!(b.blast > a.blast, "spell {e} blast grows (0 counts)");
                match (a.effect, b.effect) {
                    (Effect::None, Effect::None) => {}
                    (Effect::Burn { dps: d0, secs: s0 }, Effect::Burn { dps: d1, secs: s1 }) => {
                        assert!(d1 > d0 && s1 > s0, "spell {e} burn grows")
                    }
                    (
                        Effect::Slow {
                            factor: f0,
                            secs: s0,
                        },
                        Effect::Slow {
                            factor: f1,
                            secs: s1,
                        },
                    ) => assert!(f1 < f0 && s1 > s0, "spell {e} slow grows"),
                    (
                        Effect::Chain {
                            jumps: j0,
                            range: r0,
                            ..
                        },
                        Effect::Chain {
                            jumps: j1,
                            range: r1,
                            ..
                        },
                    ) => assert!(j1 > j0 && r1 > r0, "spell {e} chain grows"),
                    _ => panic!("spell {e} changes effect kind between tiers"),
                }
            }
            for tier in 0..3 {
                assert_eq!(
                    ladder.get(tier).hold_secs,
                    SPELLS[0].get(tier).hold_secs,
                    "spell {e} shares the hold rhythm"
                );
            }
        }
    }

    #[test]
    fn only_neutral_tier_two_one_shots() {
        // The §1.5 balance pin: neutral tier 2 (34) is the only spell
        // whose top tier kills a full zombie outright; the elements pay
        // for their jobs with instant damage.
        assert_eq!(SPELLS[0].get(2).damage, 34.0);
        assert!(SPELLS[0].get(2).damage >= ZOMBIE_HP);
        for (i, ladder) in SPELLS.iter().skip(1).enumerate() {
            assert!(
                ladder.get(2).damage < ZOMBIE_HP,
                "spell {} tier 2 must not one-shot",
                i + 1
            );
        }
    }

    /// Place `spots.len()` crowd bodies and park the rest.
    fn knot(g: &mut CityAction, spots: &[(f32, f32)]) {
        for i in 0..MAX_CROWD {
            let bi = CityAction::body_idx(i);
            if let Some(&(x, z)) = spots.get(i) {
                g.crowd[i].parked = false;
                g.write_kind(i, KIND_COP);
                g.bodies[bi].revive(x, z);
            } else {
                g.crowd[i].parked = true;
                g.bodies[bi].state = BodyState::Dead;
            }
        }
    }

    #[test]
    fn a_fire_tier_one_knot_burns_out_in_three_seconds() {
        // §1.5's fire promise: tier 1 deals 16 up front and 5 dps for
        // 3 s — 31 total. Nobody dies at the impact; the whole knot is
        // ash 3 s later.
        let mut g = playing();
        knot(&mut g, &[(0.0, 4.9), (0.8, 5.2), (-0.8, 5.2)]);
        g.spell = Element::Fire;
        g.buttons.set_host(ActionId::Ranged, true);
        step_n(&mut g, 30); // a 0.5 s hold: tier 1
        assert_eq!(SPELLS[Element::Fire.index()].tier(g.charge_t), 1);
        g.buttons.set_host(ActionId::Ranged, false);
        step_n(&mut g, 40); // cast, flight, impact
        assert_eq!(g.kills, 0, "the impact alone (16) kills nobody at 30 HP");
        assert_eq!(g.state_value()["burning"], 3, "the whole knot is burning");
        step_n(&mut g, 200); // the 3 s burn runs its course
        assert_eq!(g.kills, 3, "16 + 15 of burn: all three burn out");
    }

    #[test]
    fn ice_tier_two_slows_the_crowd_to_forty_percent() {
        let mut g = playing();
        solo(&mut g, 0, 0.0, -4.0); // 10 m ahead of the hero
        g.spell = Element::Ice;
        g.buttons.set_host(ActionId::Ranged, true);
        step_n(&mut g, 66); // tier 2
        g.buttons.set_host(ActionId::Ranged, false);
        let bi = CityAction::body_idx(0);
        let mut landed = false;
        for _ in 0..120 {
            g.step(DT);
            if g.bodies[bi].status.slow_until > g.t {
                landed = true;
                break;
            }
        }
        assert!(landed, "the ice bolt connected");
        assert_eq!(g.bodies[bi].speed_scale(g.t), 0.40);
        // Let the knockback slide die out, then measure one second of
        // the hunt: it must cover zombie_speed x pace x 0.40 of ground.
        step_n(&mut g, 30);
        let (x0, z0) = (g.bodies[bi].x, g.bodies[bi].z);
        step_n(&mut g, 60);
        let (x1, z1) = (g.bodies[bi].x, g.bodies[bi].z);
        let moved = (x1 - x0).hypot(z1 - z0);
        let want = g.spec.zombie_speed * g.crowd[0].pace * 0.40;
        assert!(
            (moved - want).abs() < want * 0.3,
            "the slowed hunt covers {moved} m in 1 s, want ~{want}"
        );
    }

