    #[test]
    fn the_chip_skips_unowned_spells() {
        let mut g = playing();
        g.spells_owned = [true, false, true, false]; // neutral + ice only
        assert_eq!(g.spell, Element::Neutral);
        g.cycle_spell();
        assert_eq!(g.spell, Element::Ice, "fire is skipped: not owned");
        g.cycle_spell();
        assert_eq!(g.spell, Element::Neutral, "and back around");
        // The Q key is the same door.
        assert!(<CityAction as crate::kit_host::KitHost>::on_key(
            &mut g, "q", true
        ));
        assert_eq!(g.spell, Element::Ice);
        // And so is the chip on the screen.
        let (cc, _) = g.chip_layout(390.0, 844.0);
        g.touch_ev(
            PointerEvent {
                id: 9,
                x: cc.0,
                y: cc.1,
                phase: PointerPhase::Begin,
                pressure: 1.0,
            },
            390,
            844,
        );
        assert_eq!(g.spell, Element::Neutral, "the chip cycles too");
    }

    #[test]
    fn a_swipe_on_the_magic_button_cycles_without_casting() {
        // Saka's element-switch call (device-feedback round,
        // 2026-11-19): a horizontal stroke on the MAGIC button
        // cycles the element — right forward, left back — and the
        // stroke is spent entirely: it never casts and never
        // starts a charge. The button's colour already follows
        // the selection (the shipped tint rule); the swipe is the
        // new road to it, next to the chip and the Q key.
        let (w, h) = (390u32, 844u32);
        let mut g = playing();
        solo(&mut g, 0, 0.0, -20.0); // one far body: bolts stay in flight
        let ((_, _), (rc, _)) = g.btn_layout(w as f32, h as f32);
        let ev = |id: u32, x: f32, y: f32, phase: PointerPhase| PointerEvent {
            id,
            x,
            y,
            phase,
            pressure: 1.0,
        };
        assert_eq!(g.spell, Element::Neutral);
        // A right stroke: one step forward, nothing else.
        g.touch_ev(ev(7, rc.0, rc.1, PointerPhase::Begin), w, h);
        g.touch_ev(ev(7, rc.0 + 40.0, rc.1, PointerPhase::Move), w, h);
        assert_eq!(g.spell, Element::Fire, "the right stroke steps forward");
        assert!(!g.charging, "a swipe never starts a charge");
        let (_, fired, _) = g.buttons.counts(ActionId::Ranged);
        assert_eq!(fired, 0, "the press was spent by the swipe, not fired");
        // The same stroke running on does not step again.
        g.touch_ev(ev(7, rc.0 + 90.0, rc.1, PointerPhase::Move), w, h);
        assert_eq!(g.spell, Element::Fire, "one stroke, one step");
        g.touch_ev(ev(7, rc.0 + 90.0, rc.1, PointerPhase::End), w, h);
        for _ in 0..40 {
            g.step(DT);
            assert!(g.projectiles.is_empty(), "a swipe never casts");
            assert_ne!(g.action, HeroAction::Shoot);
        }
        // A left stroke steps back, and from the first element it
        // wraps to the last owned one.
        g.touch_ev(ev(8, rc.0, rc.1, PointerPhase::Begin), w, h);
        g.touch_ev(ev(8, rc.0 - 40.0, rc.1, PointerPhase::Move), w, h);
        assert_eq!(g.spell, Element::Neutral, "the left stroke steps back");
        g.touch_ev(ev(8, rc.0 - 40.0, rc.1, PointerPhase::End), w, h);
        g.touch_ev(ev(9, rc.0, rc.1, PointerPhase::Begin), w, h);
        g.touch_ev(ev(9, rc.0 - 40.0, rc.1, PointerPhase::Move), w, h);
        assert_eq!(g.spell, Element::Thunder, "and wraps around the wheel");
        g.touch_ev(ev(9, rc.0 - 40.0, rc.1, PointerPhase::End), w, h);
        // A swipe that begins mid-charge cancels the charge: the
        // element moves on and the gathered bolt never leaves.
        g.touch_ev(ev(10, rc.0, rc.1, PointerPhase::Begin), w, h);
        step_n(&mut g, 3);
        assert!(g.charging, "the press gathered a charge first");
        g.touch_ev(ev(10, rc.0 + 40.0, rc.1, PointerPhase::Move), w, h);
        assert_eq!(g.spell, Element::Neutral, "the wheel wrapped forward");
        assert!(!g.charging, "the swipe spent the charge");
        g.touch_ev(ev(10, rc.0 + 40.0, rc.1, PointerPhase::End), w, h);
        for _ in 0..40 {
            g.step(DT);
            assert!(g.projectiles.is_empty(), "the cancelled charge never fires");
        }
    }

    #[test]
    fn a_tap_on_the_magic_button_still_casts_and_a_short_drag_still_charges() {
        // The swipe's neighbours keep their shipped meanings
        // (device-feedback round guard): a tap with no stroke is
        // the cast it always was, and a drag under the swipe
        // threshold is a hold — the charge climbs as before.
        let (w, h) = (390u32, 844u32);
        let ev = |id: u32, x: f32, y: f32, phase: PointerPhase| PointerEvent {
            id,
            x,
            y,
            phase,
            pressure: 1.0,
        };
        // Tap: Begin and End on the spot.
        let mut g = playing();
        solo(&mut g, 0, 0.0, -20.0);
        let ((_, _), (rc, _)) = g.btn_layout(w as f32, h as f32);
        g.touch_ev(ev(5, rc.0, rc.1, PointerPhase::Begin), w, h);
        g.touch_ev(ev(5, rc.0, rc.1, PointerPhase::End), w, h);
        step_n(&mut g, 30);
        assert_eq!(g.spell, Element::Neutral, "a tap does not cycle");
        assert_eq!(g.projectiles.len(), 1, "a tap still casts");
        // Short drag: 10 px is a hold, not a stroke.
        let mut g = playing();
        solo(&mut g, 0, 0.0, -20.0);
        g.touch_ev(ev(6, rc.0, rc.1, PointerPhase::Begin), w, h);
        g.touch_ev(ev(6, rc.0 + 10.0, rc.1, PointerPhase::Move), w, h);
        assert_eq!(g.spell, Element::Neutral, "a short drag does not cycle");
        step_n(&mut g, 30);
        assert!(g.charging, "the hold gathers its charge");
        assert!(g.charge_t > 0.45, "past the tier-1 line: {}", g.charge_t);
        g.touch_ev(ev(6, rc.0 + 10.0, rc.1, PointerPhase::End), w, h);
        step_n(&mut g, 30);
        assert_eq!(g.projectiles.len(), 1, "the held charge still fires");
    }

    #[test]
    fn bosses_two_and_three_wait_out_the_breathing_interval() {
        // The device-feedback round's pacing fix (2026-11-19): at
        // Saka's 477-kill pace every kill trigger is met long
        // before the previous boss falls, so bosses 2 and 3
        // arrived back to back. After a kill, the next boss's
        // trigger cannot fire for BOSS_REST_SECS (scaled by the
        // stage's boss_secs like the triggers) — the road back
        // into the run. Boss 1 is never held, and a slow player
        // whose trigger comes later never feels the floor at all.
        let mut g = playing();
        g.bodies[0].hp = 10000.0;
        g.bodies[0].max_hp = 10000.0;
        g.kills = 500; // every kill trigger in the stage is met
                       // Boss 1 keeps its plain trigger: it enters at once.
        g.maybe_spawn_boss();
        assert_eq!(g.boss.which, BOSS_MUTANT);
        assert!(matches!(g.boss.state, BossState::Spawning));
        // It falls at t=100; the corpse beat plays out to Idle.
        g.stage_t = 100.0;
        g.on_boss_kill();
        assert!(g.boss_down[0]);
        g.boss.state = BossState::Idle;
        let rest = BOSS_REST_SECS * g.stage_def().boss_secs;
        // One second before the interval ends, boss 2's kill
        // trigger is long met — and still it waits.
        g.stage_t = 100.0 + rest - 1.0;
        assert!(g.kills >= BOSSES[BOSS_HULK].at_kills, "the trigger is met");
        g.maybe_spawn_boss();
        assert!(
            matches!(g.boss.state, BossState::Idle),
            "boss 2 waits out the breathing interval"
        );
        // The interval over: boss 2 enters on its met trigger.
        g.stage_t = 100.0 + rest + 1.0;
        g.maybe_spawn_boss();
        assert_eq!(g.boss.which, BOSS_HULK);
        assert!(matches!(g.boss.state, BossState::Spawning));
    }

    #[test]
    fn the_hp_bar_colour_bands_are_the_classic_progression() {
        // Saka's spec for the grown HP bar (device-feedback round,
        // 2026-11-19): green while healthy, yellow when hurt, red
        // in the pity zone — the band edges pinned, not eyeballed.
        assert_eq!(hero_hp_color(1.0), [110, 220, 130, 235]);
        assert_eq!(hero_hp_color(0.51), [110, 220, 130, 235]);
        assert_eq!(hero_hp_color(0.5), [255, 200, 90, 235]);
        assert_eq!(hero_hp_color(0.26), [255, 200, 90, 235]);
        assert_eq!(hero_hp_color(0.25), [255, 110, 90, 235]);
        assert_eq!(hero_hp_color(0.0), [255, 110, 90, 235]);
    }

    #[test]
    fn a_duplicate_begin_is_the_same_tap() {
        // The 2026-11-14 double-delivery guard: a page that hands the
        // kit the same contact's Begin twice must not cycle a chip two
        // steps (from neutral, two-step cycling would alternate ice /
        // neutral and never rest on fire). One contact, one step; the
        // next contact steps again.
        let mut g = playing();
        let (cc, _) = g.chip_layout(390.0, 844.0);
        let tap = |g: &mut CityAction, id: u32, x: f32, y: f32, phase: PointerPhase| {
            g.touch_ev(
                PointerEvent {
                    id,
                    x,
                    y,
                    phase,
                    pressure: 1.0,
                },
                390,
                844,
            );
        };
        tap(&mut g, 42, cc.0, cc.1, PointerPhase::Begin);
        tap(&mut g, 42, cc.0, cc.1, PointerPhase::Begin);
        assert_eq!(g.spell, Element::Fire, "one tap, one step");
        tap(&mut g, 42, cc.0, cc.1, PointerPhase::End);
        tap(&mut g, 43, cc.0, cc.1, PointerPhase::Begin);
        assert_eq!(g.spell, Element::Ice, "the next contact steps again");
    }

    #[test]
    fn the_chip_never_overlaps_the_buttons() {
        // The chip's geometry, pinned: the spell chip (r 30s since the
        // 2026-11-14 device fix) clears MELEE, MAGIC and the spot
        // reserved for DODGE at phone and landscape sizes alike.
        let g = playing();
        for (w, h) in [(390.0f32, 844.0f32), (844.0, 390.0), (1280.0, 720.0)] {
            let ((hc, hr), (rc, rr)) = g.btn_layout(w, h);
            let (cc, cr) = g.chip_layout(w, h);
            let s = hud_scale(w, h);
            let dodge = (w - 72.0 * s, h - 190.0 * s);
            let apart = |a: (f32, f32), ar: f32, b: (f32, f32), br: f32| {
                (a.0 - b.0).hypot(a.1 - b.1) > ar + br
            };
            assert!(apart(cc, cr, hc, hr), "chip vs melee at {w}x{h}");
            assert!(apart(cc, cr, rc, rr), "chip vs magic at {w}x{h}");
            assert!(
                apart(cc, cr, dodge, 28.0 * s),
                "chip vs the reserved dodge at {w}x{h}"
            );
        }
    }

    #[test]
    fn the_sword_table_is_pinned() {
        // v3 design §2.3's standard row for the first three cuts,
        // extended by the motion round's depths 4-6, damages
        // trimmed by the simplification round so the longer mash
        // (cuts + spin + the finale's big shot) stays under the
        // ult. (The table held six swords until the variation
        // system was removed, 2026-11-15.)
        assert_eq!(SWORD.id, "arming_sword");
        assert_eq!(SWORD.tempo, 1.0);
        assert_eq!(SWORD.len(), 6);
        // (radius, half-angle deg, damage, knockback, hitstop, poise)
        let rows: [(f32, f32, f32, f32, f32, f32); 6] = [
            (1.6, 50.0, 10.0, 5.0, 0.045, 10.0),
            (1.6, 50.0, 9.0, 5.0, 0.045, 10.0),
            (1.7, 60.0, 12.0, 8.5, 0.09, 10.0),
            (1.6, 55.0, 7.0, 5.5, 0.05, 10.0),
            (1.7, 55.0, 7.0, 6.0, 0.055, 12.0),
            (1.7, 60.0, 10.0, 8.0, 0.08, 12.0),
        ];
        let deg_of = |r: f32| r * 180.0 / std::f32::consts::PI;
        let mut sum_dmg = 0.0f32;
        for (i, (radius, half, dmg, kb, hs, poise)) in rows.iter().enumerate() {
            let st = SWORD.stage(i);
            assert_eq!(st.def.radius, *radius, "stage {i} radius");
            assert!(
                (deg_of(st.def.half_angle) - half).abs() < 0.01,
                "stage {i} half-angle"
            );
            assert_eq!(st.def.damage, *dmg, "stage {i} damage");
            assert_eq!(st.def.knockback, *kb, "stage {i} knockback");
            assert_eq!(st.def.hitstop, *hs, "stage {i} hitstop");
            assert_eq!(st.def.poise_damage, *poise, "stage {i} poise");
            assert_eq!(st.def.hitstun, 0.2, "stage {i} hitstun");
            assert_eq!(st.def.fly, i == 2, "stage {i}: only the finisher flies");
            assert_eq!(
                st.step_speed,
                [2.0, 2.0, 3.2, 2.2, 2.4, 3.0][i],
                "stage {i} step-in"
            );
            assert_eq!(st.def.effect, Effect::None, "the sword is plain");
            sum_dmg += st.def.damage;
        }
        // A 30 HP zombie dies to one full combo.
        assert!(sum_dmg >= 30.0, "combo totals {sum_dmg}");
    }

    #[test]
    fn the_sword_keeps_the_measured_phase_and_a_sane_fan() {
        // The design §2.3 invariants: tempo rescales time, never the
        // phase the blow lands at; and no fan strays wide again.
        // The phases are the motion round clips' measured peaks
        // (the §1.4 record on the baked GLB).
        let phases = [0.4333f32, 0.5500, 0.2354, 0.4611, 0.4026, 0.2348];
        for (i, &want) in phases.iter().enumerate() {
            let st = SWORD.stage(i);
            let phase = st.hit_at / st.total;
            assert!(
                (phase - want).abs() < 1e-3,
                "stage {i} phase {phase} vs {want}"
            );
            let half = st.def.half_angle * 180.0 / std::f32::consts::PI;
            assert!(
                (45.0..=70.0).contains(&half),
                "stage {i} half-angle {half} out of 45..=70"
            );
        }
    }

