        // light, its own shell on block 0, and a save that flows.
        let plain = CityAction::from_json("{}").unwrap();
        assert!(!plain.bg_exp);
        assert_eq!(plain.stage_def().sky, STAGES[0].sky);
        assert_eq!(plain.doc.exposure, None);
        assert!(crate::kit_host::KitHost::save_json(&plain).is_some());
        let b0 = plain
            .doc
            .props
            .iter()
            .find(|p| p.id == "prop:block-0")
            .unwrap();
        assert_eq!(b0.gltf.as_deref(), Some(BLOCK_MODELS[0]));
        // The switch the page merges from `?look=bg`: the grade
        // arrives on stage 1's exact tuning, and the save silences
        // so an experiment session never writes the campaign's.
        let bg = CityAction::from_json("{\"look\": \"bg\"}").unwrap();
        assert!(bg.bg_exp);
