    #[test]
    fn the_companion_showcase_rides_the_look_switch_only() {
        // No switch in the world: the shipped game — one equipped
        // companion at most, a save that flows, no mates anywhere
        // in the document.
        let plain = CityAction::from_json("{}").unwrap();
        assert!(!plain.showcase);
        assert!(crate::kit_host::KitHost::save_json(&plain).is_some());
        assert_eq!(
            plain
                .doc
                .walkers
                .iter()
                .filter(|w| w.id.starts_with("walker:comp"))
                .count(),
            1,
            "the shipped game walks the one equipped companion"
        );
        assert!(
            !plain
                .doc
                .points
                .iter()
                .any(|c| c.id.contains("nightshade") || c.id.contains("leonard")),
            "no mate rings in the shipped doc"
        );

        // The switch the page merges from `?look=companions`, over
        // a save that cleared the campaign and brings Leonard: the
        // showcase overrides the save on both counts (stage 1,
        // Megan in the primary slot, the mates beside her) and
        // silences the save, so the watching never writes the
        // campaign's.
        let mut g = CityAction::from_json(
            "{\"look\": \"companions\", \"save\": {\"cleared\": 3, \
             \"best_score\": [100, 200, 300], \
             \"meta\": {\"v\": 1, \"coins\": 5000, \"lifetime\": 5000, \
             \"owned\": [\"wep.standard\", \"comp.megan\", \"comp.leonard\", \
             \"comp.nightshade\"], \
             \"equipped\": {\"weapon\": \"wep.standard\", \
             \"companion\": \"comp.leonard\"}, \
             \"upgrades\": {}, \"loop\": 1, \"loop_sel\": 1}}}",
        )
        .unwrap();
        assert!(g.showcase);
        assert_eq!(g.stage, 0, "the diorama is always stage 1");
        assert!(crate::kit_host::KitHost::save_json(&g).is_none());
        assert_eq!(
            g.companion_idx,
            Some(COMP_MEGAN),
            "Megan walks the primary slot, not the save's Leonard"
        );
        assert_eq!(g.showcase_mates[0].idx, COMP_NIGHTSHADE);
        assert_eq!(g.showcase_mates[1].idx, COMP_LEONARD);
        // All three stand in the title document already, each on
        // her own model, each wearing her ring.
        for def in COMPANION_DEFS {
            assert!(
                g.doc
                    .walkers
                    .iter()
                    .any(|w| w.gltf.as_deref() == Some(def.glb)),
                "{} stands in the doc",
                def.id
            );
        }
        for ring in [
            "fx:companion-ring",
            "fx:companion-ring-nightshade",
            "fx:aura-ring-leonard",
        ] {
            assert!(
                g.doc.points.iter().any(|c| c.id == ring),
                "{ring} is declared"
            );
        }
        // The mates stand on their stations, not on Megan's.
        for m in g.showcase_mates.iter() {
            let (ax, az) = m.core.anchor(g.hero, g.face);
            let d = (ax - m.core.x).hypot(az - m.core.z);
            assert!(
                d < 1e-4,
                "{} placed on her station: {d}",
                COMPANION_DEFS[m.idx].id
            );
        }
        let spread = (g.showcase_mates[0].core.x - g.showcase_mates[1].core.x)
            .hypot(g.showcase_mates[0].core.z - g.showcase_mates[1].core.z);
        assert!(spread > 1.0, "the stations spread the trio: {spread}");

        // The run opens at once — no select beat, however much
        // history the save carries — with the hero already
        // scratched to the showcase fraction.
        g.confirm();
        assert!(!g.selecting, "the diorama never waits on the beat");
        let frac = g.bodies[0].hp / g.bodies[0].max_hp;
        assert!(
            (frac - SHOWCASE_HERO_HP_FRAC).abs() < 1e-4,
            "the hero opens scratched: {frac}"
        );
    }

    #[test]
    fn the_showcase_trio_plays_their_roles_and_files_nothing() {
        let mut g = CityAction::from_json("{\"look\": \"companions\"}").unwrap();
        g.confirm();
        assert!(!g.selecting);
        // Half a minute of diorama: the crowd converges on the
        // plaza, Megan heals the scratched hero, Nightshade casts
        // at the converging bodies, Leonard's aura holds the hero
        // (his station is inside its radius) — and none of the
        // campaign's machinery ever turns: no mission is offered,
        // no boss is scheduled, nothing is filed.
        let mut aura_seen = false;
        let mut aura_channel_pinned = false;
        for _ in 0..(30.0 * 60.0) as usize {
            if g.level_pending {
                g.apply_choice(g.level_choices[0]);
            }
            g.step(DT);
            aura_seen |= g.aura_on;
            if g.aura_on && !aura_channel_pinned {
                // The aura's speed channel, read in the showcase
                // while nothing else composes over it (no passives
                // picked yet, no upgrades owned): exactly +8%.
                assert!(
                    (g.speed_mult() - (1.0 + AURA_SPEED_BONUS)).abs() < 1e-6,
                    "the aura's speed channel reads in the showcase: {}",
                    g.speed_mult()
                );
                aura_channel_pinned = true;
            }
            assert!(g.mission.is_none(), "no missions in the diorama");
            assert!(!g.bodies[BOSS_INDEX].alive(), "no boss is ever scheduled");
            assert!(!g.stage_clear, "the diorama never clears");
        }
        assert!(
            g.companion_heals >= 1,
            "Megan healed: {}",
            g.companion_heals
        );
        assert!(
            g.companion_bolts >= 1,
            "Nightshade cast her bolt: {}",
            g.companion_bolts
        );
        assert!(aura_seen, "Leonard's aura held the hero");
        assert!(aura_channel_pinned, "the aura channel was there to pin");
        // The hero is still standing (the diorama's revive saw to
        // it, however the half minute went) and the session still
        // files nothing.
        assert!(g.bodies[0].alive(), "the hero is on his feet");
        assert!(g.core.stats.alive, "no death was ever filed");
        assert!(crate::kit_host::KitHost::save_json(&g).is_none());
    }

    #[test]
    fn the_bg_atmosphere_dresses_only_the_bg_doc() {
        // The default game: the magic clouds only, no decals, no
        // clutter, lamp halos at the shipped values — the doc is
        // the shipped game's, prop for prop.
        let plain = CityAction::from_json("{}").unwrap();
        // One magic cloud per fx kind (32 since the meta round's
        // gilded spark variants joined the table) + the hero ring
        // (the 2026-11-18 port from world_survivor rides every doc)
        // + the companion's role ring (companion-fix round,
        // 2026-11-19: Megan is the default companion, so her green
        // ring rides every doc too).
        assert_eq!(
            plain.doc.points.len(),
            magic_fx_spec().kinds.len() + 2,
            "magic clouds + hero ring + companion ring"
        );
        let count = |g: &CityAction, prefix: &str| {
            g.doc
                .props
                .iter()
                .filter(|p| p.id.starts_with(prefix))
                .count()
        };
        assert_eq!(count(&plain, "prop:bg-decal-"), 0);
        assert_eq!(count(&plain, "prop:bg-clutter-"), 0);
        let glow = plain
            .doc
            .props
            .iter()
            .find(|p| p.id == "prop:lampglow-0")
            .unwrap();
        assert_eq!(glow.emissive, Some(2.1));
        assert_eq!(glow.scale, [0.30, 0.30, 0.30]);

        // BG mode: the atmosphere pool joins the doc after the
        // magic clouds, primed at reset — mist is on the streets
        // from the first frame, at ankle height. (The +1 over the
        // shipped count is the companion's role ring again.)
        let bg = CityAction::from_json("{\"look\": \"bg\"}").unwrap();
        assert_eq!(
            bg.doc.points.len(),
            magic_fx_spec().kinds.len() + 3 + 2,
            "magic + atmosphere clouds + hero ring + companion ring"
        );
        let mist = bg
            .doc
            .points
            .iter()
            .find(|c| c.id == "fx-0-mist_a")
            .unwrap();
        assert!(!mist.positions.is_empty(), "mist primed at boot");
        assert!(
            mist.positions.iter().all(|p| (0.2..=1.1).contains(&p[1])),
            "mist rides at ankle height"
        );
        let ash = bg
            .doc
            .points
            .iter()
            .find(|c| c.id == "fx-2-ash_mote")
            .unwrap();
        assert!(!ash.positions.is_empty(), "ash primed at boot");
        assert_eq!(count(&bg, "prop:bg-decal-"), BG_DECALS.len());
        if glb_ready(CRATE_GLB) && glb_ready(RUBBLE_GLB) && glb_ready(FENCE_GLB) {
            assert_eq!(count(&bg, "prop:bg-clutter-"), BG_CLUTTER.len());
        }
        // Decals lie flat over the road paint, textured.
        let d0 = bg
            .doc
            .props
            .iter()
            .find(|p| p.id == "prop:bg-decal-0")
            .unwrap();
        assert_eq!(d0.position[1], 0.05);
        assert!(d0
            .texture
            .as_deref()
            .is_some_and(|t| t.starts_with("image2d:")));
    }

    #[test]
    fn bg_lamp_halos_flicker_on_the_atmosphere_clock() {
        let mut bg = CityAction::from_json("{\"look\": \"bg\"}").unwrap();
        let glow_e = |g: &CityAction| {
            g.doc
                .props
                .iter()
                .find(|p| p.id == "prop:lampglow-0")
                .unwrap()
                .emissive
                .unwrap()
        };
        // Lamp 0 owns the first sputter window (t in [0, 2.4)):
        // sampling it finely must catch hard dips, and every sample
        // stays inside the floored flicker band.
        let mut min = f32::MAX;
        let mut saw_change = false;
        let mut prev = glow_e(&bg);
        for i in 1..48 {
            bg.atmo_t = i as f32 * 0.05;
            bg.build_doc();
            let e = glow_e(&bg);
            assert!((0.5..=2.1).contains(&e), "halo out of band: {e}");
            min = min.min(e);
            saw_change |= (e - prev).abs() > 0.01;
            prev = e;
        }
        assert!(saw_change, "the halo breathes");
        assert!(min < 1.2, "the sputter dips hard: min {min}");
    }

    #[test]
    fn the_ambience_cues_only_in_bg_mode() {
        crate::mixer::reset_mixer();
        let mut bg = CityAction::from_json("{\"look\": \"bg\"}").unwrap();
        bg.attract(DT);
        assert!(
            oneshots().iter().any(|s| s == AMBIENCE_CUE),
            "the wind is cued on the bg title"
        );
        // And re-cued as the loop's end approaches.
        crate::mixer::reset_mixer();
        bg.atmo_t = AMBIENCE_LOOP_SECS;
        bg.attract(DT);
        assert!(
            oneshots().iter().any(|s| s == AMBIENCE_CUE),
            "the wind is re-cued at the loop seam"
        );
        // The default game never cues it, however long it idles.
        crate::mixer::reset_mixer();
        let mut plain = CityAction::from_json("{}").unwrap();
        for _ in 0..120 {
            plain.attract(DT);
        }
        assert!(
            !oneshots().iter().any(|s| s == AMBIENCE_CUE),
            "the default game stays silent"
        );
    }

