    #[test]
    fn the_xp_curve_and_gem_table_are_pinned() {
        // Dusk Horde's curve verbatim: 5 out of level 1, +4 a level.
        assert_eq!(xp_need(1), 5);
        assert_eq!(xp_need(2), 9);
        assert_eq!(xp_need(3), 13);
        assert_eq!(xp_need(6), 25);
        // The gem table: normals pay 1, the heavy 2, the elites pay
        // up, and the bosses pay in bursts (see spawn_boss_drops).
        assert_eq!(KIND_XP.len(), ENEMY_KINDS.len());
        assert_eq!(KIND_XP[KIND_COP], 1);
        assert_eq!(KIND_XP[KIND_GOBLIN], 1);
        assert_eq!(KIND_XP[KIND_VEGAS], 2);
        assert_eq!(KIND_XP[KIND_PARASITE], 5);
        assert_eq!(KIND_XP[KIND_BRUTE], 8);
        assert_eq!(BOSS_XP, [15, 20, 30]);
        // The opening hook, pinned arithmetically: the first level
        // costs exactly five normal kills — inside the first
        // half-minute of contact at the tier-0 spawn pace.
        assert_eq!(xp_need(1), 5 * KIND_XP[KIND_COP]);
    }

    #[test]
    fn a_kill_leaves_a_gem_and_collecting_it_banks_xp() {
        let mut g = playing();
        let kind = g.crowd[0].kind;
        let id = g.bodies[1].id;
        g.on_kill(id);
        // The gem rides its own list, at the kill's feet, pulled by
        // the shipped magnet and on the drop's clock.
        assert_eq!(g.gems.items.len(), 1);
        let (gx, gz) = {
            let gem = &g.gems.items[0];
            assert_eq!(gem.kind, ItemKind::Gem(KIND_XP[kind]));
            assert_eq!(gem.magnet, DROP_MAGNET_R);
            assert_eq!(gem.ttl, Some(GEM_TTL));
            (gem.x, gem.z)
        };
        assert_eq!(g.state_value()["gems"], 1);
        // Walk onto it: the walk-over banks the XP.
        stand_on(&mut g, gx, gz);
        step_n(&mut g, 1);
        assert_eq!(g.picked_gem, 1);
        assert_eq!(g.xp, KIND_XP[kind]);
        assert!(g.gems.items.is_empty());
        assert!(!g.level_pending, "one gem is not a level yet");
    }

    #[test]
    fn the_level_up_opens_at_the_threshold_heals_and_freezes() {
        let mut g = playing();
        solo(&mut g, 0, 3.0, 3.0);
        g.bodies[0].hp = 50.0;
        g.bank_xp(4);
        assert!(!g.level_pending);
        assert_eq!(g.level, 1);
        g.bank_xp(1);
        // The level lands: +1, the bank spent, Moonlit's 30% heal in.
        assert_eq!(g.level, 2);
        assert_eq!(g.xp, 0);
        assert!(g.level_pending);
        assert!((g.bodies[0].hp - 80.0).abs() < 0.01, "50 + 30% of 100");
        let v = g.state_value();
        assert_eq!(v["level"], 2);
        assert_eq!(v["xp_need"], 9);
        assert_eq!(v["level_pending"], true);
        // Three distinct passives are on the table.
        let names: Vec<&str> = g.level_choices.iter().map(|c| c.name()).collect();
        assert_eq!(names.len(), 3);
        assert!(names.iter().all(|n| *n != "RECOVER"));
        let mut sorted = names.clone();
        sorted.sort_unstable();
        sorted.dedup();
        assert_eq!(sorted.len(), 3, "the draw never repeats a card");
        // And the world is frozen solid while the cards are up:
        // clocks, hero and hunter alike.
        let (t0, stage0, hero0) = (g.t, g.stage_t, g.hero);
        let z0 = (g.bodies[1].x, g.bodies[1].z);
        step_n(&mut g, 30);
        assert_eq!(g.t, t0);
        assert_eq!(g.stage_t, stage0);
        assert_eq!(g.hero, hero0);
        assert_eq!((g.bodies[1].x, g.bodies[1].z), z0);
    }

