    #[test]
    fn a_level_up_earned_mid_combo_waits_for_the_chain_to_end() {
        // Saka's stress point (2026-11-17): the cards used to open
        // over a combo in flight. Now the level lands — heal, ult
        // refill and all — but the showing waits for the chain.
        let mut g = playing();
        solo(&mut g, 0, 0.0, 4.5);
        g.crowd[0].cd_left = 999.0;
        g.buttons.set_host(ActionId::Melee, true);
        g.buttons.set_host(ActionId::Melee, false);
        for _ in 0..30 {
            g.step(DT);
            if g.action == HeroAction::Swing {
                break;
            }
        }
        assert_eq!(g.action, HeroAction::Swing);
        assert!(g.combo.active(), "the chain is in flight");
        g.bank_xp(xp_need(1));
        assert_eq!(g.level, 2, "the level itself landed");
        assert!(g.level_held, "the showing is held");
        assert!(!g.level_pending, "no cards over the combo");
        assert_eq!(g.ult_gauge, ULT_GAUGE_MAX, "the refill landed too");
        let mut opened_mid_combo = false;
        let mut steps = 0;
        while !g.level_pending && steps < 600 {
            g.step(DT);
            steps += 1;
            if g.level_pending && g.combo.active() {
                opened_mid_combo = true;
            }
        }
        assert!(g.level_pending, "the cards open once the chain ends");
        assert!(!opened_mid_combo, "never over a live chain");
    }

