    #[test]
    fn a_purchase_persists_across_a_reload_and_starts_in_hand() {
        // 1000 coins in the save; SWIFT costs 400 (META-DESIGN §3.1).
        let mut g = saved_kit(
            "{\"meta\": {\"v\": 1, \"coins\": 1000, \"lifetime\": 1000, \
             \"owned\": [\"wep.standard\", \"comp.megan\"], \
             \"equipped\": {\"weapon\": \"wep.standard\", \"companion\": \"comp.megan\"}, \
             \"upgrades\": {}, \"loop\": 1, \"loop_sel\": 1}}",
        );
        assert_eq!(g.meta.coins, 1000);
        let swift = g
            .spec
            .meta
            .catalog
            .iter()
            .position(|e| e.id == "wep.swift")
            .unwrap();
        g.catalog_tap_weapon(swift);
        assert_eq!(g.meta.coins, 600);
        assert!(g.meta.owns("wep.swift"));
        assert_eq!(
            g.meta.equipped_weapon, "wep.standard",
            "buying does not equip"
        );
        g.catalog_tap_weapon(swift);
        assert_eq!(g.meta.equipped_weapon, "wep.swift", "an owned row equips");
        // The save round-trip: what the page persists is what loads.
        let save =
            crate::kit_host::KitHost::save_json(&g).expect("a save outside the bg experiment");
        let mut g2 = CityAction::from_json(&format!("{{\"save\": {save}}}")).unwrap();
        assert_eq!(g2.meta.coins, 600);
        assert!(g2.meta.owns("wep.swift"));
        assert_eq!(g2.meta.equipped_weapon, "wep.swift");
        // And the next run starts with SWIFT in hand — an index
        // swap at reset, no model work (the no-rebake rule).
        g2.confirm();
        assert_eq!(g2.weapon_idx, W_SWIFT);
        assert_eq!(g2.state_value()["weapon"], "short_blade");
        assert_eq!(g2.state_value()["equipped_weapon"], "wep.swift");
    }

    #[test]
    fn upgrades_apply_at_run_start_through_their_channels() {
        // A maxed wallet's levels (META-DESIGN §5): atk 10, hp 10,
        // spd 5, gauge 5 — each lands on its own channel only.
        let mut g = saved_kit(
            "{\"meta\": {\"v\": 1, \"coins\": 0, \"lifetime\": 0, \
             \"owned\": [\"wep.standard\", \"comp.megan\"], \
             \"equipped\": {\"weapon\": \"wep.standard\", \"companion\": \"comp.megan\"}, \
             \"upgrades\": {\"atk\": 10, \"hp\": 10, \"spd\": 5, \"gauge\": 5}, \
             \"loop\": 1, \"loop_sel\": 1}}",
        );
        g.confirm();
        assert!(!g.selecting, "no history: the run starts at once");
        // HP: +10 per level flat on the shipped base.
        assert_eq!(g.bodies[0].max_hp, HERO_HP + 100.0);
        assert_eq!(g.bodies[0].hp, HERO_HP + 100.0);
        // ATK: x(1 + 0.03 x 10) on the power channel.
        assert!((g.power_mult() - 1.3).abs() < 1e-6, "{}", g.power_mult());
        // SPD: x(1 + 0.015 x 5) on the speed channel.
        assert!((g.speed_mult() - 1.075).abs() < 1e-6, "{}", g.speed_mult());
        // GAUGE: one landed hit's gain is x(1 + 0.04 x 5) = x1.2.
        g.gain_hits(1);
        assert!(
            (g.ult_gauge - ULT_GAIN_HIT * 1.2).abs() < 1e-6,
            "{}",
            g.ult_gauge
        );
    }

    #[test]
    fn a_star_tier_gilds_the_sword_and_its_damage() {
        // STANDARD at tier 2 (META-DESIGN §4): +4% damage through
        // the power channel, and the ult sword grows and gilds.
        let mut g = saved_kit(
            "{\"meta\": {\"v\": 1, \"coins\": 0, \"lifetime\": 0, \
             \"owned\": [\"wep.standard\", \"wep.standard.2\", \"comp.megan\"], \
             \"equipped\": {\"weapon\": \"wep.standard\", \"companion\": \"comp.megan\"}, \
             \"upgrades\": {}, \"loop\": 1, \"loop_sel\": 1}}",
        );
        g.confirm();
        assert_eq!(g.star_tier_now(), 2);
        assert!((g.power_mult() - 1.04).abs() < 1e-6, "{}", g.power_mult());
        assert_eq!(g.state_value()["star_tiers"][0], 2);
        let (scale, tint, glow, glow_color) = g.star_sword_look();
        assert_eq!(scale, 2.2);
        assert_eq!(tint, [255, 214, 130]);
        assert!(
            (glow - 0.90).abs() < 1e-6,
            "the tier glow over the shipped base"
        );
        assert_eq!(glow_color, [1.0, 214.0 / 255.0, 130.0 / 255.0]);
        // Tier 1 is the shipped sword exactly — the look a fresh
        // campaign has always had.
        let g1 = playing();
        assert_eq!(g1.star_tier_now(), 1);
        let (scale, tint, glow, glow_color) = g1.star_sword_look();
        assert_eq!(scale, ULT_SWORD_SCALE);
        assert_eq!(tint, [255, 255, 255]);
        assert_eq!(glow, 0.55);
        assert_eq!(glow_color, [1.0, 0.78, 0.32]);
        // The gilded spark kinds exist beside their bases, same
        // frames, tier tints — declared with the pool, so a starred
        // sword's first cut introduces nothing mid-run. (M2 appended
        // Megan's heal sparkle after them: 32 + 1.)
        let spec = magic_fx_spec();
        assert_eq!(spec.kinds.len(), 33);
        assert_eq!(spec.kinds[FX_HEAL_SPARKLE].name, "heal_sparkle");
        assert_eq!(spec.kinds[FX_HEAL_SPARKLE].color, [110, 255, 170]);
        assert_eq!(
            spec.kinds[star_spark_kind(FX_MELEE_SPARK, 2)].color,
            [255, 217, 145]
        );
        assert_eq!(
            spec.kinds[star_spark_kind(FX_MELEE_SPARK, 3)].color,
            STAR_TINT3
        );
        assert_eq!(star_spark_kind(FX_MELEE_SPARK, 1), FX_MELEE_SPARK);
    }

    #[test]
    fn weapon_models_ride_the_catalog_entries() {
        // The weapons round fills META-DESIGN §3.4's `model` field:
        // every arsenal weapon names its Synty GLB, and the entry
        // is what the run reads — no second table to drift.
        let spec = CityActionSpec::default();
        let want = [
            "assets/models/city/wep_standard.glb",
            "assets/models/city/wep_swift.glb",
            "assets/models/city/wep_heavy.glb",
            "assets/models/city/wep_ember.glb",
            "assets/models/city/wep_frost.glb",
            "assets/models/city/wep_volt.glb",
        ];
        for (idx, path) in want.iter().enumerate() {
            let entry = spec.meta.weapon_entry(idx).expect("weapon entry");
            assert_eq!(entry.model.as_deref(), Some(*path), "weapon {idx}");
        }
        // The read follows the weapon in hand, nothing else.
        let mut g = playing();
        for (idx, path) in want.iter().enumerate() {
            g.weapon_idx = idx;
            assert_eq!(g.weapon_model_now(), Some(*path), "weapon {idx}");
        }
    }

    #[test]
    fn the_weapon_norm_matches_standard_to_the_item_sword() {
        // Measured total lengths (2026-11-19, from the GLBs):
        // Sword_01 1.544 m, the item sword 1.570 m. The uniform
        // factor puts STANDARD's normalized length on the item
        // sword's, and being uniform it preserves the six models'
        // relative sizes by construction.
        let raw_standard = std::hint::black_box(1.544_f32);
        assert!((raw_standard * WEAPON_MODEL_NORM - 1.570).abs() < 0.01);
    }

    #[test]
    fn frost_wears_ice_at_tier_one_and_gold_from_tier_two() {
        // FROST ★1: the ice read is the weapon's base tint on the
        // ult-sword channel (no blue blade exists in the pack).
        let mut g = saved_kit(
            "{\"meta\": {\"v\": 1, \"coins\": 0, \"lifetime\": 0, \
             \"owned\": [\"wep.frost\", \"comp.megan\"], \
             \"equipped\": {\"weapon\": \"wep.frost\", \"companion\": \"comp.megan\"}, \
             \"upgrades\": {}, \"loop\": 1, \"loop_sel\": 1}}",
        );
        g.confirm();
        assert_eq!(g.weapon_idx, W_FROST);
        assert_eq!(g.star_tier_now(), 1);
        let (scale, tint, glow, glow_color) = g.star_sword_look();
        assert_eq!(scale, ULT_SWORD_SCALE);
        assert_eq!(tint, FROST_TINT);
        assert_eq!(glow, 0.55, "the shipped base glow, cooled not cut");
        assert_eq!(glow_color, FROST_GLOW);
        // FROST ★2: the tier's set replaces the base tint — the
        // precedence is ★ over weapon, so a gilded FROST reads
        // exactly like a gilded STANDARD (model aside).
        let mut g = saved_kit(
            "{\"meta\": {\"v\": 1, \"coins\": 0, \"lifetime\": 0, \
             \"owned\": [\"wep.frost\", \"wep.frost.2\", \"comp.megan\"], \
             \"equipped\": {\"weapon\": \"wep.frost\", \"companion\": \"comp.megan\"}, \
             \"upgrades\": {}, \"loop\": 1, \"loop_sel\": 1}}",
        );
        g.confirm();
        assert_eq!(g.star_tier_now(), 2);
        let (scale, tint, glow, _) = g.star_sword_look();
        assert_eq!(scale, 2.2);
        assert_eq!(tint, [255, 214, 130]);
        assert!((glow - 0.90).abs() < 1e-6);
        // A non-FROST weapon at ★1 keeps the shipped neutral base.
        let g = playing();
        assert_eq!(g.weapon_idx, W_STANDARD);
        let (_, tint, _, glow_color) = g.star_sword_look();
        assert_eq!(tint, [255, 255, 255]);
        assert_eq!(glow_color, [1.0, 0.78, 0.32]);
    }

    #[test]
    fn weapon_switches_keep_the_gpu_mesh_key() {
        // All six Synty models are declared at doc build whichever
        // weapon the run holds (the first-occurrence rule): an
        // equip — catalog or mission card — never moves the key,
        // the same pin M2 put on companion switches.
        let mut keys = Vec::new();
        for id in [
            "wep.standard",
            "wep.swift",
            "wep.heavy",
            "wep.ember",
            "wep.frost",
            "wep.volt",
        ] {
            let save = format!(
                "{{\"meta\": {{\"v\": 1, \"coins\": 0, \"lifetime\": 0, \
                 \"owned\": [\"{id}\", \"comp.megan\"], \
                 \"equipped\": {{\"weapon\": \"{id}\", \"companion\": \"comp.megan\"}}, \
                 \"upgrades\": {{}}, \"loop\": 1, \"loop_sel\": 1}}}}"
            );
            let mut g = saved_kit(&save);
            g.confirm();
            g.build_doc();
            if glb_ready("assets/models/city/wep_standard.glb") {
                for idx in 0..WEAPONS.len() {
                    let path = g.weapon_model_now_for(idx).expect("weapon model");
                    assert!(
                        g.doc
                            .props
                            .iter()
                            .any(|p| p.gltf.as_deref() == Some(path) && !p.enabled),
                        "{path} is declared with {id} equipped"
                    );
                }
            }
            keys.push(g.doc.gpu_mesh_key());
        }
        for w in keys.windows(2) {
            assert_eq!(w[0], w[1], "a weapon switch keeps the mesh key");
        }
    }

    #[test]
    fn the_ult_swings_the_equipped_weapons_model() {
        // EMBER equipped: the cast's giant sword is Sword_15's
        // model at the ★1 scale times the set's norm — an index
        // read into the declared prop set, never a rebuild.
        let mut g = saved_kit(
            "{\"meta\": {\"v\": 1, \"coins\": 0, \"lifetime\": 0, \
             \"owned\": [\"wep.ember\", \"comp.megan\"], \
             \"equipped\": {\"weapon\": \"wep.ember\", \"companion\": \"comp.megan\"}, \
             \"upgrades\": {}, \"loop\": 1, \"loop_sel\": 1}}",
        );
        g.confirm();
        assert_eq!(g.weapon_idx, W_EMBER);
        assert_eq!(
            g.weapon_model_now(),
            Some("assets/models/city/wep_ember.glb")
        );
        g.ult_gauge = ULT_GAUGE_MAX;
        ult_press(&mut g);
        step_n(&mut g, 1);
        assert_eq!(g.action, HeroAction::Ult);
        g.build_doc();
        let sword = g
            .doc
            .props
            .iter()
            .find(|p| p.id == "prop:ult-sword")
            .expect("the ult sword prop rides the doc");
        if glb_ready("assets/models/city/wep_ember.glb") {
            assert_eq!(
                sword.gltf.as_deref(),
                Some("assets/models/city/wep_ember.glb")
            );
            let want = ULT_SWORD_SCALE * WEAPON_MODEL_NORM;
            assert!(
                (sword.scale[0] - want).abs() < 1e-6,
                "scale {} vs {want}",
                sword.scale[0]
            );
        } else if glb_ready(ULT_SWORD_GLB) {
            // The fallback chain, for a tree without the Synty
            // files mounted: the item sword at the bare ★ scale.
            assert_eq!(sword.gltf.as_deref(), Some(ULT_SWORD_GLB));
            assert!((sword.scale[0] - ULT_SWORD_SCALE).abs() < 1e-6);
        }
    }

    #[test]
    fn the_potion_norms_match_the_shipped_presentation_sizes() {
        // Measured native heights (heal prep, 2026-11-19, from the
        // GLBs): Bottle_11 0.389 m, Bottle_14 0.388 m. The norms
        // put them on the tiers' shipped presentation sizes — the
        // snack's ≈0.45 m and the plate's ≈0.62 m.
        assert!((0.389 * POTION_SMALL_NORM - 0.45).abs() < 0.01);
        assert!((0.388 * POTION_LARGE_NORM - 0.62).abs() < 0.01);
    }

    #[test]
    fn heal_items_wear_the_potion_models() {
        // Both heal tiers draw their Synty flask at the tier's
        // norm (modulo the ±5% presentation pulse), and both
        // models are declared at doc build whichever tier is on
        // the ground — the first-occurrence rule, as with the
        // weapons. Heal amounts and drop rules are not read here;
        // they never moved.
        let mut g = playing();
        g.spawn_drop(ItemKind::HealSmall, 5.0, 5.0);
        g.spawn_drop(ItemKind::HealLarge, 6.0, 6.0);
        g.build_doc();
        if glb_ready(ITEM_POTION_SMALL_GLB) {
            for path in ITEM_GLBS {
                assert!(
                    g.doc
                        .props
                        .iter()
                        .any(|p| p.gltf.as_deref() == Some(path) && !p.enabled),
                    "{path} is declared at doc build"
                );
            }
        }
        for p in g.pickups.items.iter() {
            let (want_glb, norm) = match p.kind {
                ItemKind::HealSmall => (ITEM_POTION_SMALL_GLB, POTION_SMALL_NORM),
                ItemKind::HealLarge => (ITEM_POTION_LARGE_GLB, POTION_LARGE_NORM),
                _ => continue,
            };
            let prop = g
                .doc
                .props
                .iter()
                .find(|q| q.id == format!("prop:item-{}", p.id))
                .unwrap_or_else(|| panic!("the {:?} pickup rides the doc", p.kind));
            if glb_ready(want_glb) {
                assert_eq!(prop.gltf.as_deref(), Some(want_glb), "{:?}", p.kind);
                assert!(
                    prop.scale[0] >= norm && prop.scale[0] <= norm * 1.06,
                    "{:?} scale {} vs norm {norm} (pulse band)",
                    p.kind,
                    prop.scale[0]
                );
                // Base-origin flasks stand lower than the old
                // centre-origin hover: base inside 0.27..0.37.
                assert!(
                    (0.27..0.37).contains(&prop.position[1]),
                    "{:?} base y {}",
                    p.kind,
                    prop.position[1]
                );
            }
        }
    }

    #[test]
    fn the_beat_opens_after_any_recorded_run_for_the_catalog() {
        // One recorded death — no clear, one stage — still opens
        // the beat on the next confirm: the wallet (or the wish
        // for one) is reason enough (META-DESIGN §1.2's pacing).
        let mut g = saved_kit("{\"best_score\": [100, null, null]}");
        g.confirm();
        assert!(g.selecting, "a recorded run opens the beat");
        // The catalog opens and closes over the beat.
        g.cataloging = true;
        let layout = catalog_layout(390.0, 844.0, &g.spec.meta);
        assert!(g.catalog_tap(layout.back[0] + 5.0, layout.back[1] + 5.0, 390.0, 844.0));
        assert!(!g.cataloging);
    }

    #[test]
    fn the_catalog_screen_draws_clean_and_answers_taps() {
        let mut g = saved_kit(
            "{\"cleared\": 1, \"best_score\": [100, null, null], \
             \"meta\": {\"v\": 1, \"coins\": 1000, \"lifetime\": 1000, \
             \"owned\": [\"wep.standard\", \"comp.megan\"], \
             \"equipped\": {\"weapon\": \"wep.standard\", \"companion\": \"comp.megan\"}, \
             \"upgrades\": {}, \"loop\": 1, \"loop_sel\": 1}}",
        );
        g.confirm();
        assert!(g.selecting);
        // The beat itself carries the wallet and the door.
        let beat = g.hud(390, 844, false);
        let beat_texts: Vec<&str> = beat.texts.iter().map(|t| t.text.as_str()).collect();
        assert!(beat_texts.contains(&"CATALOG"));
        assert!(beat_texts.contains(&"COINS 1000"));
        g.cataloging = true;
        let list = g.hud(390, 844, false);
        let texts: Vec<&str> = list.texts.iter().map(|t| t.text.as_str()).collect();
        for want in [
            "CATALOG",
            "ARSENAL",
            "UPGRADES",
            "COINS 1000",
            "SWIFT",
            "ATK Lv 0/10",
        ] {
            assert!(
                texts.iter().any(|t| t.contains(want)),
                "missing {want} in {texts:?}"
            );
        }
        let issues = crate::hud_lint::check(&list, 390, 844);
        assert!(issues.is_empty(), "{issues:?}");
        // A tap on SWIFT's row buys it: 1000 - 400 = 600.
        let layout = catalog_layout(390.0, 844.0, &g.spec.meta);
        let swift_idx = g
            .spec
            .meta
            .catalog
            .iter()
            .position(|e| e.id == "wep.swift")
            .unwrap();
        let row = layout
            .rows
            .iter()
            .find(|r| r.entry == Some(swift_idx))
            .unwrap();
        assert!(g.catalog_tap(row.rect[0] + 20.0, row.rect[1] + 10.0, 390.0, 844.0));
        assert_eq!(g.meta.coins, 600);
        assert!(g.meta.owns("wep.swift"));
        // An ATK level costs 150: the row buys it.
        let up = layout.rows.iter().find(|r| r.upgrade == Some(0)).unwrap();
        assert!(g.catalog_tap(up.rect[0] + 20.0, up.rect[1] + 10.0, 390.0, 844.0));
        assert_eq!(g.meta.coins, 450);
        assert_eq!(g.meta.upgrades.level("atk"), 1);
        // With the wallet drained, the next tap posts the notice
        // and changes nothing.
        g.meta.coins = 0;
        assert!(g.catalog_tap(up.rect[0] + 20.0, up.rect[1] + 10.0, 390.0, 844.0));
        assert_eq!(g.meta.upgrades.level("atk"), 1);
        assert!(g.catalog_notice > 0.0);
    }

    #[test]
    fn a_duplicated_tap_delivery_buys_nothing_twice() {
        // The shell delivers one physical tap on the touch stream
        // and again on the pointer path, pixel-identical. On the
        // catalog's door the second delivery lands on the GAUGE row
        // under the button and would buy it unasked — seen live in
        // the M1 probe (1000 -> 800 on open). The beat records the
        // tap it acted on and swallows the repeat.
        let mut g = saved_kit(
            "{\"cleared\": 1, \"best_score\": [100, null, null], \
             \"meta\": {\"v\": 1, \"coins\": 1000, \"lifetime\": 1000, \
             \"owned\": [\"wep.standard\", \"comp.megan\"], \
             \"equipped\": {\"weapon\": \"wep.standard\", \"companion\": \"comp.megan\"}, \
             \"upgrades\": {}, \"loop\": 1, \"loop_sel\": 1}}",
        );
        g.confirm();
        assert!(g.selecting);
        let (w, h) = (390, 844);
        let btn = catalog_button_rect(w as f32, h as f32);
        let (bx, by) = (btn[0] + btn[2] / 2.0, btn[1] + btn[3] / 2.0);
        // The first delivery opens the catalog.
        assert!(crate::kit_host::KitHost::pointer(&mut g, bx, by, w, h));
        assert!(g.cataloging);
        // The duplicate delivery at the same pixel is swallowed:
        // the screen stays open and nothing is bought.
        assert!(crate::kit_host::KitHost::pointer(&mut g, bx, by, w, h));
        assert!(g.cataloging);
        assert_eq!(g.meta.coins, 1000, "the duplicate bought nothing");
        assert_eq!(g.meta.upgrades.level("gauge"), 0);
        // A genuine later tap still works: step the beat past the
        // duplicate window, then tap SWIFT's row and buy it.
        step_n(&mut g, 40);
        let layout = catalog_layout(w as f32, h as f32, &g.spec.meta);
        let swift_idx = g
            .spec
            .meta
            .catalog
            .iter()
            .position(|e| e.id == "wep.swift")
            .unwrap();
        let row = layout
            .rows
            .iter()
            .find(|r| r.entry == Some(swift_idx))
            .unwrap();
        assert!(crate::kit_host::KitHost::pointer(
            &mut g,
            row.rect[0] + 20.0,
            row.rect[1] + 10.0,
            w,
            h
        ));
        assert_eq!(g.meta.coins, 600);
        assert!(g.meta.owns("wep.swift"));
    }

