    #[test]
    fn stage_two_scales_the_fight() {
        let mut g = saved_kit("{\"cleared\": 1, \"best_score\": [100, null, null]}");
        g.confirm();
        g.pick_stage(1);
        // Bodies: +4 on the tier count, x1.25 HP.
        assert_eq!(g.active_target(), 28);
        solo(&mut g, 0, 8.0, 8.0);
        assert_eq!(g.bodies[CityAction::body_idx(0)].max_hp, 30.0 * 1.25);
        // The tier ladder climbs at 0.85x: T1's 60 s line is 51 s.
        g.stage_t = 51.1;
        step_n(&mut g, 2);
        assert_eq!(g.tier, 1);
        // The Hulk opens the stage, at 0.85x its trigger and x1.2 HP.
        let mut g = saved_kit("{\"cleared\": 1, \"best_score\": [100, null, null]}");
        g.confirm();
        g.pick_stage(1);
        g.stage_t = BOSSES[BOSS_HULK].at_secs * 0.85 + 1.0;
        step_n(&mut g, 2);
        assert_eq!(g.boss.which, BOSS_HULK);
        assert_eq!(g.bodies[BOSS_INDEX].max_hp, 880.0 * 1.2);
        // Its fall opens T3 by position, though it is not the Mutant.
        kill_boss(&mut g, BOSS_HULK);
        assert!(g.boss_down[0]);
    }

