    #[test]
    fn the_weapon_table_is_pinned() {
        // The v3 §2.3 rows, restored as data: ids, tempos, per-stage
        // damage and the elemental rows' effects. Damages trimmed
        // by the simplification round (the mash grew a finale;
        // every path stays under the ult — the ladder test pins
        // the totals).
        let ids = [
            "arming_sword",
            "short_blade",
            "broadsword",
            "ember_sword",
            "frost_sword",
            "volt_sword",
        ];
        for (i, w) in WEAPONS.iter().enumerate() {
            assert_eq!(w.id, ids[i]);
            assert_eq!(w.len(), 6, "the motion round's six cuts");
        }
        assert_eq!(WEAPONS[W_STANDARD].tempo, 1.0);
        assert_eq!(WEAPONS[W_SWIFT].tempo, 1.25);
        assert_eq!(WEAPONS[W_HEAVY].tempo, 0.8);
        let dmg = |wi: usize| {
            [
                WEAPONS[wi].stage(0).def.damage,
                WEAPONS[wi].stage(1).def.damage,
                WEAPONS[wi].stage(2).def.damage,
                WEAPONS[wi].stage(3).def.damage,
                WEAPONS[wi].stage(4).def.damage,
                WEAPONS[wi].stage(5).def.damage,
            ]
        };
        assert_eq!(dmg(W_STANDARD), [10.0, 9.0, 12.0, 7.0, 7.0, 10.0]);
        assert_eq!(dmg(W_SWIFT), [7.0, 7.0, 11.0, 7.0, 8.0, 10.0]);
        assert_eq!(dmg(W_HEAVY), [12.0, 12.0, 16.0, 13.0, 14.0, 15.0]);
        assert_eq!(dmg(W_EMBER), [8.0, 8.0, 11.0, 8.0, 9.0, 10.0]);
        assert_eq!(dmg(W_FROST), [8.0, 8.0, 11.0, 8.0, 9.0, 10.0]);
        assert_eq!(dmg(W_VOLT), [8.0, 8.0, 11.0, 8.0, 9.0, 10.0]);
        assert_eq!(
            WEAPONS[W_EMBER].stage(0).def.effect,
            Effect::Burn {
                dps: 2.0,
                secs: 1.5
            }
        );
        assert_eq!(
            WEAPONS[W_FROST].stage(2).def.effect,
            Effect::Slow {
                factor: 0.6,
                secs: 2.0
            }
        );
        assert_eq!(
            WEAPONS[W_VOLT].stage(0).def.effect,
            Effect::Chain {
                jumps: 1,
                range: 2.0,
                scale: 0.4
            }
        );
        assert_eq!(weapon_element(&WEAPONS[W_STANDARD]), Element::Neutral);
        assert_eq!(weapon_element(&WEAPONS[W_EMBER]), Element::Fire);
        assert_eq!(weapon_element(&WEAPONS[W_FROST]), Element::Ice);
        assert_eq!(weapon_element(&WEAPONS[W_VOLT]), Element::Thunder);
        // The identities in one line each: HEAVY's fan is the
        // widest, SWIFT's tempo makes its stages the shortest.
        assert!(
            WEAPONS[W_HEAVY].stage(0).def.half_angle > WEAPONS[W_STANDARD].stage(0).def.half_angle
        );
        assert!(WEAPONS[W_SWIFT].stage(0).total < WEAPONS[W_STANDARD].stage(0).total);
        assert!(WEAPONS[W_HEAVY].stage(0).total > WEAPONS[W_STANDARD].stage(0).total);
    }

    #[test]
    fn a_mission_start_raises_the_banner_and_a_failure_names_itself() {
        // The objective lines, in the readout's shorthand.
        let slay = Mission {
            kind: MissionKind::Slay,
            target_kind: 0,
            left: 17,
            total: 17,
            secs: MISSION_SLAY_SECS,
            total_secs: MISSION_SLAY_SECS,
        };
        assert_eq!(slay.banner_objective(), "SLAY 17 - 25s");
        let hunt = Mission {
            kind: MissionKind::KindSlay,
            target_kind: KIND_GOBLIN,
            left: 6,
            total: 6,
            secs: MISSION_KIND_SECS,
            total_secs: MISSION_KIND_SECS,
        };
        assert_eq!(hunt.banner_objective(), "HUNT GOBLINS x6 - 30s");
        let ult = Mission {
            kind: MissionKind::UltSlay,
            target_kind: 0,
            left: 8,
            total: 8,
            secs: MISSION_ULT_SECS,
            total_secs: MISSION_ULT_SECS,
        };
        assert_eq!(ult.banner_objective(), "ULT SLAY 8 - 30s");
        // A start raises the banner with the rolled mission's line.
        let mut g = playing();
        g.mission_next = 0.0;
        step_n(&mut g, 1);
        let m = g.mission.expect("the first mission started");
        let v = g.state_value();
        assert_eq!(v["mission_banner"]["title"], "MISSION START");
        assert_eq!(v["mission_banner"]["objective"], m.banner_objective());
        // A failure is announced too, briefly, then clears.
        g.mission = Some(Mission { secs: 0.05, ..slay });
        step_n(&mut g, 10);
        assert!(g.mission.is_none(), "the clock ran out");
        let v = g.state_value();
        assert_eq!(v["mission_banner"]["title"], "MISSION FAILED");
        step_n(&mut g, 90);
        assert_eq!(
            g.state_value()["mission_banner"],
            Value::Null,
            "the failure banner clears"
        );
    }

    #[test]
    fn the_centre_banners_hold_while_a_card_modal_is_up() {
        // The monkey caught the mission banner's objective line
        // drawn under a level-up card: the corridor packs feed
        // levels faster now, so the two centre pieces share a
        // moment the old layout never produced. The modal owns
        // the centre; the banners wait (their timers freeze with
        // the sim under the modal, so nothing is lost).
        let mut g = playing();
        g.mission_next = 0.0;
        step_n(&mut g, 1);
        let objective = g
            .mission
            .expect("the first mission started")
            .banner_objective();
        let texts: Vec<String> = g
            .hud(390, 844, false)
            .texts
            .iter()
            .map(|t| t.text.clone())
            .collect();
        assert!(
            texts.iter().any(|t| t == &objective),
            "the banner shows in open play: {texts:?}"
        );
        g.level_pending = true;
        let texts: Vec<String> = g
            .hud(390, 844, false)
            .texts
            .iter()
            .map(|t| t.text.clone())
            .collect();
        assert!(
            texts.iter().any(|t| t == "LEVEL UP"),
            "the modal is up: {texts:?}"
        );
        assert!(
            !texts
                .iter()
                .any(|t| t == &objective || t == "MISSION START"),
            "no banner line under the cards: {texts:?}"
        );
        g.level_pending = false;
        g.weapon_pending = true;
        let texts: Vec<String> = g
            .hud(390, 844, false)
            .texts
            .iter()
            .map(|t| t.text.clone())
            .collect();
        assert!(
            !texts
                .iter()
                .any(|t| t == &objective || t == "MISSION START"),
            "no banner line under the prize cards either: {texts:?}"
        );
    }

    #[test]
    fn a_mission_starts_on_schedule_and_its_kills_open_the_weapon_cards() {
        let mut g = playing();
        step_n(&mut g, 60);
        assert!(g.mission.is_none(), "nothing before the first slot");
        g.mission_next = 0.0;
        step_n(&mut g, 1);
        assert!(g.mission.is_some(), "the first mission starts");
        // A known quota for a deterministic count.
        g.mission = Some(Mission {
            kind: MissionKind::Slay,
            target_kind: 0,
            left: 2,
            total: 2,
            secs: MISSION_SLAY_SECS,
            total_secs: MISSION_SLAY_SECS,
        });
        g.on_kill(100);
        assert_eq!(g.mission.map(|m| m.left), Some(1));
        assert!(!g.weapon_pending);
        g.on_kill(101);
        assert!(g.mission.is_none(), "the quota is met");
        assert_eq!(g.missions_done, 1);
        assert!(g.weapon_pending, "the prize cards open on the spot");
        assert!(
            g.weapon_choices.iter().all(|&i| i != g.weapon_idx),
            "the sword in hand is never offered"
        );
        // The world is frozen behind the cards.
        let t0 = g.stage_t;
        step_n(&mut g, 30);
        assert_eq!(g.stage_t, t0, "the sim waits for the pick");
    }

