    #[test]
    fn a_weapon_card_pick_swaps_the_sword_as_data() {
        let mut g = playing();
        g.open_weapon_cards();
        assert!(g.weapon_pending);
        let slot = match g.weapon_choices.iter().position(|&i| i == W_EMBER) {
            Some(s) => s,
            None => {
                g.weapon_choices[0] = W_EMBER;
                0
            }
        };
        let pickups_before = g.pickups.items.len();
        // Tap the card (the phone path, like the level cards).
        let (w, h) = (390u32, 844u32);
        let r = level_card_rects(w as f32, h as f32)[slot];
        let ev = |phase| PointerEvent {
            id: 7,
            x: r[0] + r[2] * 0.5,
            y: r[1] + r[3] * 0.5,
            phase,
            pressure: 1.0,
        };
        g.touch_ev(ev(PointerPhase::Begin), w, h);
        g.touch_ev(ev(PointerPhase::End), w, h);
        assert!(!g.weapon_pending, "the pick closes the cards");
        assert_eq!(g.weapon_idx, W_EMBER);
        assert_eq!(g.weapon().id, "ember_sword");
        assert_eq!(g.state_value()["weapon"], "ember_sword");
        assert_eq!(g.state_value()["weapon_name"], "EMBER");
        // Data only: nothing fell to the ground — the pickup list
        // is exactly what it was before the swap.
        assert_eq!(g.pickups.items.len(), pickups_before);
    }

